import { useState } from "react";
import styled from "styled-components";

const Container = styled.div`
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: #111;
  color: white;
  display: flex;
  justify-content: flex-start;
  align-items: center;
  flex-direction: column;
  transition: height 0.3s ease-in-out;
  height: ${({ $isOpen }) => ($isOpen ? "300px" : "50px")};
  overflow: hidden;
  z-index: 1000;
  border-top-right-radius: 40px;
  border-top-left-radius: 40px;
`;

const FormWrapper = styled.div`
    width: 100%;
    max-width: 1400px;
    margin-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: opacity 0.3s ease-in-out;
  opacity: ${({ $isOpen }) => ($isOpen ? "1" : "0")};
  pointer-events: ${({ $isOpen }) => ($isOpen ? "auto" : "none")};
  @media screen and (max-width:768px){
        flex-direction: column;
        justify-content: center;
        align-items: center;
    }
`;
const TextBox = styled.div`
`
const Brand = styled.p`
    margin-bottom: 5px;
    @media screen and (max-width:768px){
        text-align: center;
    }
`
const Title = styled.h2`
    
`
const Ul = styled.ul`
    display: flex;
    gap: 10px;
    @media screen and (max-width:768px){
        margin-bottom: 20px;
    }
`
const Li = styled.li`
    display: flex;
    flex-direction: column;
    gap: 5px;
`
const Name = styled.label`
    
`
const Input = styled.input`
 width: 100%;
 height: 50px;
  padding: 0 20px;
  border: 1px solid #ccc;
  border-radius: 10px;
  background: white;
  color: #000;

  &::placeholder{
    color: #ccc;
  }
`;

const Select = styled.select`
    width: 220px;
    height: 50px;
  padding: 0 20px;
  border: 1px solid #ccc;
  border-radius: 10px;
  background: white;
  color: #ccc;
  @media screen and (max-width:768px){
        width: 150px;
    }
`;

const Button = styled.button`
  width: 100%;
  background: ${( props ) => (props.$isOpen ? "#656565" : "#111")};
  color: #fff;
  font-size: 18px;
  padding: 15px 16px;
  border: none;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
`;
const BtnImg = styled.img`
    
`
const BtnSpan = styled.span`
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 5px;
`
const Send = styled.button`
    width: 220px;
    height: 75px;
    font-size: 25px;
    font-weight: 800;
    background: #f5c900;
    color: #fff;
    padding: 12px 16px;
    border: none;
    border-radius: 20px;
    cursor: pointer;
`
export default function Inquiry() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <Container $isOpen={isOpen}>
      <Button onClick={() => setIsOpen(!isOpen)} $isOpen={isOpen}>
        {isOpen ? 
                <BtnSpan><BtnImg src="assets/iq_down.png" />간편 창업문의</BtnSpan>
                 : 
                 <BtnSpan><BtnImg src="assets/iq_up.png" />간편 창업문의</BtnSpan>
                 }
      </Button>
      <FormWrapper $isOpen={isOpen}>
        <TextBox>
            <Brand>카페봄봄</Brand>
            <Title>창업문의</Title>
        </TextBox>
        <Ul>
        <Li>
            <Name>이름</Name>
            <Input type="text" placeholder="성함을 입력해 주세요." />
        </Li>
        <Li>
            <Name>연락처</Name>
            <Input type="tel" placeholder="연락처 입력" />
        </Li>
        <Li>
        <Name>창업희망지역</Name>
        <Select>
          <option>지역 선택</option>
          <option>서울</option>
          <option>인천</option>
          <option>대전</option>
          <option>대구</option>
          <option>부산</option>
          <option>광주</option>
          <option>울산</option>
          <option>세종</option>
          <option>강원</option>
          <option>경기</option>
          <option>경남</option>
          <option>경북</option>
          <option>전남</option>
          <option>전북</option>
          <option>제주</option>
          <option>충남</option>
          <option>충북</option>
        </Select>
        </Li>
        </Ul>
        <Send>상담 신청</Send>
      </FormWrapper>
    </Container>
  );
}