import React from 'react'
import styled from 'styled-components'
import Competitiveness from '../components/franchise/Competitiveness';
import { useParams } from 'react-router-dom';
import Interior from '../components/franchise/Interior';
import Procedure from '../components/franchise/Procedure';
import Expense from '../components/franchise/Expense';
import Inquiry from '../components/franchise/Inquiry';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding-top: 6.25em;
`;

const TitleBox = styled.div`
    width: 100%;
    height: 400px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 30px;
    background: url(assets/brandbg.png) no-repeat center / cover;
    padding: 20px;
    margin-bottom: 5px;
    border-radius: 10px;
    color: #fff;
    @media screen and (max-width:768px){
      height: 200px;
    }
`;

const Title = styled.h2`
    font-size: 50px;
    @media screen and (max-width:768px){
      font-size: 30px;
    }
`;

const SubTitle = styled.p`
    font-size: 20px;
    color: #fff;
    text-align: center;
    @media screen and (max-width:768px){
      font-size: 18px;
    }
`;

const SubTitleSpan = styled.span`
    color: #fdda24;
    font-weight: bold;
`; 


function Franchise() {
    const { type } = useParams();

// 🌟 type에 따라 다른 컴포넌트 렌더링
const renderComponent = () => {
  switch (type) {
    case 'competitiveness':
      return <Competitiveness />;
    case 'interior':
      return <Interior />;
    case 'procedure':
        return <Procedure />;
    case 'expense':
        return <Expense />;
    case 'inquiry':
        return <Inquiry />
    default:
      return <Competitiveness />;
  }
};
  return (
    <Container>
        <TitleBox>
        <Title>가맹안내</Title>
        <SubTitle>차별화를 추구하여 보다 성장하는 <SubTitleSpan>Cafe 봄봄</SubTitleSpan></SubTitle>
        <SubTitleSpan>가맹문의 070.7817.1100</SubTitleSpan>
      </TitleBox>
      {renderComponent()} 
    </Container>
  )
}

export default Franchise
