import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import notices from './notices.json';

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0 0 0;

    @media screen and (max-width: 768px) {
        padding: 50px 0;
    }
`;

const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`;

const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;

    @media screen and (max-width: 768px) {
        font-size: 30px;
    }
`;
const InfoBar = styled.div`
    width: 100%;
    max-width: 1200px;
    display: flex;
    justify-content: flex-start;
    padding: 10px 0;
    font-size: 14px;
    color: #333;
`;

const TableBox = styled.div`
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
`;

const Table = styled.table`
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    border-top: 2px solid #000;
    border-bottom: 1px solid #ececec;
    text-align: center;
`;

const Col = styled.th`
    font-size: 17px;
    font-weight: 700;
    color: #1d1d1d;
    padding: 15px 0;
    border-bottom: 1px solid #ddd;
    background-color: #f9f9f9;
    text-align: center;

    /* 기본 너비 설정 */
    width: ${(props) => props.$width || 'auto'};

    /* 제목 칼럼만 유동적으로 확장 */
    &:nth-child(2) {
        width: auto;
    }

    @media screen and (max-width: 768px) {
        font-size: 12px;
        padding: 5px 0;
        width: ${(props) => props.$widthMobile || '30px'};
    }
`;


const TbodyData = styled.td`
    height: 50px;
    border-top: 1px solid #ecf0f1;
    border-bottom: 1px solid #ecf0f1;
    font-size: 15px;
    font-weight: ${(props) => (props.$highlight ? 'bold' : 'nomal')};
    color: ${(props) => (props.$isNotice ? '#f9267f' : '#333')}; 
    background-color: ${(props) => (props.$highlight ? '#fff6fa' : 'transparent')}; 

    @media screen and (max-width: 768px) {
        font-size: 12px;
    }
`;

const Pagenation = styled.div`
    margin-top: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
`;
const LeftArrow = styled.button`
  width: 30px;
  height: 30px;
  background: url(assets/storeleft.png) no-repeat 50% 50%;
  color: transparent;
  border-radius: 50%;
  &:hover {
    background-color: #000;
  }
`
const RightArrow = styled.button`
  width: 30px;
  height: 30px;
   background: url(assets/storeright.png) no-repeat 50% 50%;
   color: transparent;
   border-radius: 50%;
  &:hover {
    background-color: #000;
  }
`
const NumBtn = styled.button`
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background-color: ${(props) => (props.$active ? '#000' : '#fff')};
    color: ${(props) => (props.$active ? '#fff' : '#000')};
    font-weight: bold;
    cursor: pointer;

    &:hover {
        background-color: #000;
        color: #fff;
    }
`;

function Announcement() {
    const [data, setData] = useState([]);
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 15;

    useEffect(() => {
        setData(notices);
    }, []);

    const totalPages = Math.ceil(data.length / itemsPerPage);
    const currentItems = data.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

    return (
        <Container>
            <Title>Cafe BOMBOM Notice</Title>
            <SubTitle>봄봄 <b>공지사항</b></SubTitle>
            <InfoBar>
                Total {data.length}건 {currentPage} 페이지
            </InfoBar>
            <TableBox>
                <Table>
                    <thead>
                        <tr>
                            <Col>번호</Col>
                            <Col>제목</Col>
                            <Col>글쓴이</Col>
                            <Col>조회</Col>
                            <Col>날짜</Col>
                        </tr>
                    </thead>
                    <tbody>
                        {currentItems.map((item, index) => (
                            <tr key={item.id}>
                                <TbodyData 
                                    $highlight={currentPage === 1} 
                                    $isNotice={currentPage === 1}
                                >
                                    {currentPage === 1 ? '공지' : item.id}
                                </TbodyData>
                                <TbodyData 
                                    style={{ textAlign: 'left', paddingLeft: '10px' }} 
                                    $highlight={currentPage === 1}
                                >
                                    {item.title}
                                </TbodyData>
                                <TbodyData $highlight={currentPage === 1}>{item.author}</TbodyData>
                                <TbodyData $highlight={currentPage === 1}>{item.views}</TbodyData>
                                <TbodyData $highlight={currentPage === 1}>{item.date}</TbodyData>
                            </tr>
                        ))}
                    </tbody>
                </Table>

                {/* 페이지네이션 */}
                <Pagenation>
                {currentPage > 10 && (
    <LeftArrow onClick={() => setCurrentPage(1)}>
      맨앞
    </LeftArrow>
  )}
  
  {/* 2페이지부터 "처음" 버튼 등장 */}
  {currentPage > 1 && (
    <LeftArrow onClick={() => setCurrentPage(currentPage - 1)}>
      처음
    </LeftArrow>
  )}
  
                    {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                        <NumBtn
                            key={page}
                            $active={currentPage === page}
                            onClick={() => setCurrentPage(page)}
                        >
                            {page}
                        </NumBtn>
                    ))}
                     {currentPage < totalPages && (
    <RightArrow onClick={() => setCurrentPage(currentPage + 1)}>
      다음
    </RightArrow>
  )}
                </Pagenation>
            </TableBox>
        </Container>
    );
}

export default Announcement;
