import React from 'react'
import styled from 'styled-components'
import MainBanner from '../components/ui/Mainbanner'
import Open from '../components/layout/Open'
import Inquiry from '../components/layout/Inquiry'
import Marketing from '../components/layout/Marketing'
import Coaching from '../components/layout/Coaching'
import Boon from '../components/layout/Boon'
import Slide from '../components/layout/Slide'
import Delivery from '../components/layout/Delivery'
import Interior from '../components/layout/Interior'
import Costs from '../components/layout/Costs'
import Recommend from '../components/layout/Recommend'
import Notkor from '../components/layout/Notkor'

const Container = styled.div`
 width: 100%;
 padding-top: 6.25em;
`

function HomePage({ lang }) { 
  return (
    <Container>
      <MainBanner lang={lang} /> 
      {lang === "kor" && <Open lang={lang} />}  
      <Slide lang={lang} />
      {lang === "kor" && <Marketing lang={lang} />}  
      {lang === "kor" && <Delivery lang={lang} />}  
      {lang === "kor" && <Coaching lang={lang} />}  
      <Interior lang={lang} />
      {lang === "kor" && <Costs lang={lang} />}  
      {lang === "kor" && <Recommend lang={lang} />}  
      {lang === "kor" && <Boon lang={lang} />}  
      {lang === "kor" && <Inquiry lang={lang} />}
      {lang !== "kor" && <Notkor lang={lang} />}
    </Container>
  )
}

export default HomePage
