const snslist = [
  { id: 1, img: `${process.env.PUBLIC_URL}/assets/instar.png`, alt: "Instagram" },
  { id: 2, img: `${process.env.PUBLIC_URL}/assets/blog.png`, alt: "Blog" },
  { id: 3, img: `${process.env.PUBLIC_URL}/assets/youtube.png`, alt: "YouTube" },
  { id: 4, img: `${process.env.PUBLIC_URL}/assets/store.png`, alt: "Store" },
];

const getMenuList = (lang) => {
  switch (lang) {
    case "eng":
      return menulistEng;
    case "chn":
      return menulistChn;
    case "jpn":
      return menulistJpn;
    default:
      return menulist;
  }
};
const getLogoSrc = (lang, isMobile) => {
  if (lang === "kor") {
    return isMobile 
      ? `${process.env.PUBLIC_URL}/assets/logo_m.png`  // 🇰🇷 한국어 + 모바일 -> 모바일 로고
      : `${process.env.PUBLIC_URL}/assets/logo.png`;   // 🇰🇷 한국어 + PC -> 기본 로고
  }
  return `${process.env.PUBLIC_URL}/assets/logo.svg`;  // 🌐 다국어 -> 항상 다국어 로고
};

function Header({ lang }) {
  const [isMobile, setIsMobile] = useState(false);  // 🌸 모바일인지 체크
  const [logoSrc, setLogoSrc] = useState(getLogoSrc(lang, false));  // 🌸 초기 로고 설정
  const menulist = getMenuList(lang);

  useEffect(() => {
    // 🌸 미디어 쿼리 체크 함수
    const handleResize = () => {
      const mobile = window.innerWidth <= 950;
      setIsMobile(mobile);
      setLogoSrc(getLogoSrc(lang, mobile));  // 🌸 로고 업데이트
    };

    window.addEventListener("resize", handleResize);
    handleResize();  // 🌸 초기 체크

    return () => window.removeEventListener("resize", handleResize);
  }, [lang]);  // 🌸 언어가 바


  const homePath = lang === "kor" ? "/" : `/${lang}`;

  return (
    <Container>
      <Inner>
        {/* ✅ 로고 */}
        <Link to={homePath}>
        <Img src={logoSrc} alt="Logo"  $isMobile={isMobile} lang={lang}  />   {/* 🌟 로고 크기 조정 */}
        </Link>

        {/* ✅ 네비게이션 메뉴 */}
        <MenuBar>
          <Menu>
            {menulist.map((item) => (
              <MenuList key={item.id}>
                <MenuLink to={item.path}>{item.title}</MenuLink>

                {/* 🌸 서브메뉴가 있는 경우에만 보여줘! */}
                {(item.submenu ?? []).length > 0 && (
                  <SubMenu>
                    {item.submenu.map((subitem, index) => (
                      <SubMenuItem key={index}>
                        <SubMenuLink to={subitem.path}>
                          {subitem.title}
                        </SubMenuLink>
                      </SubMenuItem>
                    ))}
                  </SubMenu>
                )}
              </MenuList>
            ))}
          </Menu>
        </MenuBar>

        {/* ✅ 언어 선택 & SNS 아이콘 */}
        <Language>
         <LanguageBtn />
          <Sns>
            {snslist.map((sns) => (
              <SnsItem key={sns.id}>
                <SnsImg src={sns.img} alt={sns.alt} size="24px" />  {/* 🌟 SNS 아이콘 크기 조정 */}
              </SnsItem>
            ))}
          </Sns>
        </Language>
      </Inner>
    </Container>
  );
}

export default Header;
