import React, { useState } from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/franchise/franbg.png) no-repeat top left;
    background-size: cover;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0 0 0 ;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`

const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`

const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 100px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`

const CardWrapper = styled.div`
    width: 100%;
    height: 850px;
    display: flex;
    background:  ${({ bg }) => `url(${bg}) no-repeat center / cover`};
    gap: 0;
    border-radius: 16px;
    transition: background 0.3s;
`

const Card = styled.div`
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    width: calc(100% /4);
    height: 100%;
    padding: 0 20px 100px 20px;
    background: transparent;
    transition: transform 0.3s, box-shadow 0.3s, background-color 0.3s;
    white-space: pre-wrap;
    color: #fff;
    cursor: pointer;
    border-right: 1px solid rgba(255, 255, 255, .1);

    &:last-child{
        border-right: none;
    }

    &:hover {
        transform: translateY(-10px);
    }
`

const CardTitle = styled.h4`
    font-size: 28px;
    font-weight: 700;
    color: ${({ active }) => active ? "#fdda24" : "#fff"};
    letter-spacing: -1px;
    line-height: 33px;
    margin-bottom: 25px;
    transition: all 0.5s ease-in-out;
`

const CardText = styled.p`
    font-size: 14px;
    color: #fff;
    letter-spacing: -0.5px;
    line-height: 25px;
`

const Item = [
    {
        id: 1,
        title: "합리적인 가격\n전문적인 맛",
        text: "Cafe 봄봄의 커피는\n스페셜티가 함유된 고급 원두를 사용하여\n봄봄만의 맛과 풍미를 가지고 있으며 합리적인 가격에\n차별화된 크기의 맛있는 커피를 제공합니다.",
        bg: `${process.env.PUBLIC_URL}/assets/franchise/combg1.png`
    },
    {
        id: 2,
        title: "차별화 추구",
        text: "보다 저렴한, 보다 친절한, 보다 빠른 매력과 커피와 음료로\n매니아층을 형성하였고, 테이크 아웃 시장에서는 빠질 수 없는\n카페로 인정받았습니다. 현재에도 끊임없는 메뉴 개발로\n브랜드의 경쟁력을 강화하고 있습니다.",
        bg: `${process.env.PUBLIC_URL}/assets/franchise/combg2.png`
    },
    {
        id: 3,
        title: "안정적인\n매장 운영 시스템",
        text: "처음 시작하시는 점주님들을 위해 기초부터 시작해\n다양한 레시피 교육과 고객 서비스까지\n꼼꼼히 알려드리며, 안정적인 매장 운영을 하실 수 있도록\n도와드립니다.",
        bg: `${process.env.PUBLIC_URL}/assets/franchise/combg3.png`
    },
    {
        id: 4,
        title: "브랜드 안정성",
        text: "2012년 1호점 영남대점을 시작으로 꾸준한 사랑을 받으며\n2021년 400호점을 돌파하였고, 지속적인 오픈을 통해\n더욱 발전하고 있습니다. 시작을 함께 할 수 있도록\nCafe 봄봄이 도와드립니다.",
        bg: `${process.env.PUBLIC_URL}/assets/franchise/combg4.png`
    }
]

function Competitiveness() {
  const [hoverBg, setHoverBg] = useState(`${process.env.PUBLIC_URL}/assets/franchise/combg1.png`);
  const [activeIndex, setActiveIndex] = useState(1);  // 기본으로 첫 번째 카드 활성화

  const handleMouseEnter = (index, bg) => {
    setHoverBg(bg);
    setActiveIndex(index);  // 호버 시 activeIndex 업데이트
  };

  const handleMouseLeave = () => {
    setHoverBg(Item[activeIndex - 1].bg);  // activeIndex에 맞는 배경 유지
  };

  return (
    <Container>
      <Title>Cafe BOMBOM</Title>
      <SubTitle><b>차별화된 전략</b>으로<br />소비자를 만족시켜주는 Cafe 봄봄</SubTitle>
      <CardWrapper bg={hoverBg}>
        {Item.map(({ id, title, text, bg }, index) => (
          <Card
            key={id}
            active={activeIndex === index + 1}
            onMouseEnter={() => handleMouseEnter(index + 1, bg)}
            onMouseLeave={handleMouseLeave}
          >
            <CardTitle active={activeIndex === index + 1}>{title}</CardTitle>
            <CardText>{text}</CardText>
          </Card>
        ))}
      </CardWrapper>
    </Container>
  )
}

export default Competitiveness
