import React from "react";
import styled from "styled-components";
import { Routes, Route, useLocation } from "react-router-dom";  // ✅ `Router` 제거!
import Header from "./components/layout/Header";
import GlobalStyles from "./style/GlobalStyles";
import HomePage from "./pages/HomePage";
import Footer from "./components/layout/Footer";
import TopBtn from "./components/ui/TopBtn";
import BrandPage from "./pages/BrandPage";
import StorePage from "./pages/StorePage";
import View from "./components/Store/View";
import Franchise from "./pages/Franchise";
import SupportPage from "./pages/SupportPage";
import MenuPage from "./pages/MenuPage";

const Container = styled.div`
  padding: 20px;
`;

function App() {
  const location = useLocation();

  const getLanguage = () => {

    if (location.pathname.startsWith("/eng")) return "eng";
    if (location.pathname.startsWith("/chn")) return "chn";
    if (location.pathname.startsWith("/jpn")) return "jpn";
    return "kor";
  };

  const lang = getLanguage();


  return (
    <>
      <GlobalStyles />
      <Header lang={lang} />
      <Container>
        <Routes>
          <Route path="/" element={<HomePage lang={lang} />} />
          <Route path="/eng/*" element={<HomePage lang={lang} />} />
          <Route path="/chn/*" element={<HomePage lang={lang} />} />
          <Route path="/jpn/*" element={<HomePage lang={lang} />} />
          <Route path="/brand/:type" element={<BrandPage />} />
          <Route path="/store/:type" element={<StorePage />} />
          <Route path="/store/store/:id" element={<View />} />
          <Route path="/franchise/:type" element={<Franchise />} />
          <Route path="/support/:type" element={<SupportPage />} />
          <Route path="/menu/:type" element={<MenuPage />} />
        </Routes>
        <TopBtn />
        <Footer lang={lang} />
      </Container>
    </>
  );
}

export default App;
