import React, { useState } from 'react'
import styled from 'styled-components'
import { Swiper, SwiperSlide } from 'swiper/react'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'
import 'swiper/css/effect-coverflow'
import { Autoplay } from 'swiper/modules'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/franchise/franbg.png) no-repeat top left;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0 0 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`

const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
   
`

const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 30px;   
    }
`

const SwiperContainer = styled.div`
    width: 100%;
    max-width: 1200px;
    margin-bottom: 50px;
`

const SlideWrapper = styled.div`
    position: relative;
    padding-bottom: 50px;
    text-align: center;
    @media screen and (max-width:768px) {
        padding-bottom: 10px;
    }
`
const Step = styled.span`
        font-size: 16px;
    color: #fdda24;
    display: inline-block;
    line-height: 30px;
    padding: 0 10px;
    background-color: #181818;
    border-radius: 3px;
    margin-bottom: 15px;
`
const StepTitle = styled.h3`
    font-size: 23px;
    font-weight: 700;
    color: #181818;
    letter-spacing: -1px;
    line-height: 30px;
    height: 46px;
    margin-bottom: 15px;
`

const SlideImage = styled.img`
    width: 100%;
    border-radius: 12px;
    transition: transform 0.5s ease-in-out, opacity 0.5s ease-in-out;
    opacity: ${(props) => (props.$isActive ? 1 : 0.6)};

    &:hover {
        transform: scale(1.05);
    }
`

const ProgressBar = styled.div`
    width: 80%;
    height: 2px;
    background-color: #ddd;
    margin: 10px auto 20px auto;
    position: relative;
`

const Dot = styled.img`
    width: 24px;
    height: 24px;
    position: absolute;
    top: -12px;
    left: 50%;
    transform: translateX(-50%);
    transition: opacity 0.3s ease-in-out;

    &:hover {
        cursor: pointer;
    }
`

const Description = styled.p`
    font-size: 13px;
    white-space: pre;
    color: ${(props) => (props.$isActive ? '#181818' : '#aaa')};
    transition: color 0.3s ease-in-out;
`

const images = [
    `${process.env.PUBLIC_URL}/assets/franchise/step1.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step2.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step3.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step4.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step5.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step6.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step7.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step8.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step9.png`
]

const inImages = [
    `${process.env.PUBLIC_URL}/assets/franchise/step1_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step2_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step3_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step4_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step5_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step6_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step7_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step8_in.png`,
    `${process.env.PUBLIC_URL}/assets/franchise/step9_in.png`
]
const steptitle = [
    '가맹희망자 문의',
    '사업설명 및 상담',
    '점포개발 및 상권분석,점포선정완료',
    '가맹희망자 최종협의 및 점포임대차계약\n가맹계약체결문의',
    '점포실측 및 설계',
    '실내·외 공사착수 및 점포 운영교육 실시',
    'OPEN 준비',
    '점포 OPEN',
    '사후관리'


]
const descriptions = [
    '전화문의 접수(070-7817-1100)\n또는 홈페이지 접수 후에\n희망지역 확인담당자배정',
    '정보공개서 제공 및 상담',
    '점포 개설 예정지 선정, 예정지 주위의\n점포 정보 제공 및 예정지 주변의 상권분석\n(예상 수요자들의 동선 및 접근성, 타당성 분석)',
    '최종협의 후 점포임대차 계약 및\n본사와의 가맹계약체결',
    '실내·외 인테리어 도면협의 및 공사일정 확인\n투자예산규모 산출',
    '실내·외 인테리어 공사(약 22일~25일 소요)\n점포 운영교육 실시(약 10일 소요)\n점포개설에 필요한 각종 인·허가 취득완료',
    'OPEN 1일 전 기자재 및 인테리어 소품,\nPOS 입고 및 S/V를 통한 OPEN 준비 진행',
    '가맹점 OPEN 및 영업시작\n(S/V를 통한 3일간의 OPEN 지원과 점검 지도가 이루어짐)',
    '담당 S/V를 통한 점검 관리\n지속적인 신메뉴 개발'
]

function Procedure() {
  const [activeIndex, setActiveIndex] = useState(0)
  const [hoverIndex, setHoverIndex] = useState(null)

  const handleSlideChange = (swiper) => {
    setActiveIndex(swiper.realIndex)
  }

  const handleMouseEnter = (index) => {
    setHoverIndex(index)
  }

  const handleMouseLeave = () => {
    setHoverIndex(null)
  }

  return (
    <Container>
       <Title>BOMBOM Franchise</Title>
       <SubTitle>봄봄과 함께 이루어지는<br /><b>가맹개설절차 안내</b></SubTitle>
       <SwiperContainer>
          <Swiper
            modules={[Autoplay]}
            spaceBetween={30}
            slidesPerView={3}
            centeredSlides={true}
            loop={true}
            speed={800}
            autoplay={{
              delay: 3000,
              disableOnInteraction: false
            }}
            onSlideChange={handleSlideChange}
            breakpoints={{  // 🌟 반응형 설정 추가!
                1200: {  // 화면 너비가 1200px 이상일 때
                    slidesPerView: 3,
                    spaceBetween: 30,
                },
                768: {   // 화면 너비가 768px 이상일 때
                    slidesPerView: 2,
                    spaceBetween: 20,
                },
                0: {     // 화면 너비가 768px 미만일 때
                    slidesPerView: 1,
                    spaceBetween: 10,
                },
            }}
          >
            {images.map((src, index) => (
              <SwiperSlide key={index}>
                <SlideWrapper>
                    <Step>Step 0{index + 1}</Step>
                         <StepTitle>{steptitle[index]}</StepTitle>
                  <SlideImage 
                    src={
                      activeIndex === index || hoverIndex === index 
                        ? inImages[index]  // 🌟 센터거나 호버 시 _in 이미지 사용!
                        : src
                    }
                    alt={`step-${index + 1}`} 
                    $isActive={activeIndex === index}
                    onMouseEnter={() => handleMouseEnter(index)}
                    onMouseLeave={handleMouseLeave}
                  />
                  <ProgressBar>
                      <Dot 
                          src={
                              activeIndex === index || hoverIndex === index
                              ? `${process.env.PUBLIC_URL}/assets/franchise/ico_dot_in.png`  // 🌟 센터거나 호버 시 _in dot!
                              : `${process.env.PUBLIC_URL}/assets/franchise/ico_dot.png`      // 🌟 아니면 일반 dot!
                          }
                          alt="dot"
                      />
                  </ProgressBar>
                  <Description $isActive={activeIndex === index}>
                      {descriptions[index]}
                  </Description>
                </SlideWrapper>
              </SwiperSlide>
            ))}
          </Swiper>
       </SwiperContainer>
    </Container>
  )
}

export default Procedure
