import React, { useEffect } from 'react';
import { Map, MapMarker } from 'react-kakao-maps-sdk';
import styled from 'styled-components';


const TitleBox = styled.div`
    width: 100%;
     max-width: 800px;

`
const Brand = styled.span`
  font-size: 18px;
    font-weight: 600;
    color: #fdda24;
    letter-spacing: 1px;
    display: inline-block;
    margin-bottom: 20px;
`
const Title = styled.h1`
  font-weight: 300;
  font-size: 40px;
`
const Text = styled.p`
    font-size: 19px;
    color: #9b9b9b;
    line-height: 36px;
    letter-spacing: -1px;

    b {
      color: #000;
    }
`
const MapBox = styled.div`
  width: 100%;
  max-width: 800px;
  margin-top: 30px;
`



const KakaoMap = () => {
  useEffect(() => {
    // 🌟 Kakao API 로딩이 끝나면 초기화!
    if (window.kakao && window.kakao.maps) {
      window.kakao.maps.load(() => {
      });
    }
  }, []);

  return (
    <>
      <TitleBox>
          <Brand>Cafe BOMBOM Office</Brand>
          <Title>대구 <b>본사</b></Title>
          <Text><b>Add. </b>대구광역시 중구 동덕로 125(삼덕동 2가 101-1번지) 5, 6층</Text>
          <Text><b>Tel. </b>053-756-7272  <b>Fax.</b> 053-756-7373</Text>
          </TitleBox>
          <MapBox>
    <Map
      center={{ lat: 35.8658806256687, lng: 128.603054054297 }}  // 대구광역시 중구 동덕로 125 좌표
      style={{ width: "100%", height: "500px" }} 
      level={3}
    >
      <MapMarker position={{ lat: 35.8658806256687, lng: 128.603054054297 }}>
        <div style={{ padding: "5px 0 5px 17px", color: "#000", fontSize : "12px", fontWeight : "bold"  }}>대구 중구 동덕로 125</div>
      </MapMarker>
    </Map>
    </MapBox>

    <TitleBox style={{marginTop : "50px"}}>
          <Brand>Cafe BOMBOM Office</Brand>
          <Title>서울 <b>지사</b></Title>
          <Text><b>Add. </b>서울특별시 금천구 가산디지털1로 128, 18층 1808호(가산동, 에스티엑스브이타워)</Text>
          <Text><b>Tel. </b>070-8833-7275  <b>Fax.</b></Text>
          </TitleBox>
          <MapBox>
    <Map
       center={{ lat: 37.47728122595508, lng: 126.88362081533808 }} 
      style={{ width: "100%", height: "500px" }} 
      level={3}
    >
      <MapMarker position={{ lat: 37.47728122595508, lng: 126.88362081533808 }}>
        <div style={{ padding: "3px 0 5px 17px", color: "#000", fontSize : "10px", fontWeight : "bold"}}>서울 금천구 가산디지털1로 128</div>
      </MapMarker>
    </Map>
    </MapBox>
    </>
  );
};

export default KakaoMap;
