import React from 'react'
import styled from 'styled-components'
import { Swiper, SwiperSlide } from 'swiper/react'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'
import { Autoplay } from 'swiper/modules'

const Container = styled.div`
  width: 100%;
  background: url(assets/dvbg.png) no-repeat bottom;
  background-size: 100%;
  border-radius: 16px;
  padding: 120px 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  margin: 5px 0;
  @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 30px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: #774126;
`

const StyledSwiper = styled(Swiper)`
  width: 100%;      // 🌟 컨테이너에 맞춰서 크기 조절
  overflow: visible;
  .swiper-slide {
    transition: transform 0.5s ease;  // 🌟 부드럽게 변하도록 트랜지션 추가!
  }

  .swiper-slide-active {
    transform: scale(1.1);
  }
`
const SlideItem = styled.div`
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 50px 0;
`

const SlideImage = styled.img`
    width: 275px;
`
const P = styled.p`
    width: 100%;
    color: #666;
    text-align: center;
`
const IconBox = styled.div`
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    margin-top: 50px;
`
const IconImg = styled.img`
 @media screen and (max-width:1024px){
    width: 150px;
 }
 @media screen and (max-width:768px){
    width: 100px;
 }
 @media screen and (max-width:500px){
    width: 50px;
 }
`
function Delivery() {
  return (
    <Container>
           <Title>배달도 역시 <TitleSpan>카페봄봄이 대세!</TitleSpan></Title>
         <StyledSwiper
           modules={[Autoplay]}
   
           autoplay={{ delay: 3000 }}
           loop
           centeredSlides={true} 
           slidesPerView="auto" 
           breakpoints={{
               0: { slidesPerView: 1 },  // 화면이 640px 이상일 때 2개
               640 : { slidesPerView: 2 },
               1024: { slidesPerView: 3 },  // 화면이 1024px 이상일 때 3개
               1500: { slidesPerView: 5 }
             }}
           speed={1500}
         >
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_1.png" alt="dvslide_1" />
             </SlideItem>
           </SwiperSlide>
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_2.png" alt="dvslide_2" />
             </SlideItem>
           </SwiperSlide>
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_3.png" alt="dvslide_3" />
             </SlideItem>
           </SwiperSlide>
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_1.png" alt="dvslide_1" />
             </SlideItem>
           </SwiperSlide>
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_2.png" alt="dvslide_2" />
             </SlideItem>
           </SwiperSlide>
           <SwiperSlide>
             <SlideItem>
               <SlideImage src="assets/dvslide_3.png" alt="dvslide_3" />
             </SlideItem>
           </SwiperSlide>
         </StyledSwiper>
         <P>실제 배달어플 리뷰 캡쳐화면입니다.</P>
         <IconBox>
            <IconImg src='assets/dvicon_1.png' />
            <IconImg src='assets/dvicon_2.png' />
            <IconImg src='assets/dvicon_3.png' />
            <IconImg src='assets/dvch.gif' />
         </IconBox>
       </Container>
  )
}

export default Delivery
