import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/not.png) no-repeat center bottom/cover;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 120px 0;
    margin: 5px 0;
    position: relative;
    overflow: hidden;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Inner = styled.div`
    max-width: 1400px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
`
const LeftBox = styled.div`
    position: absolute;
    left: 0;
    width: 1115px;
    height: 725px;
    background: url(assets/notimg.png) no-repeat;
    z-index: 1;

    @media screen and (max-width: 1200px) {
       display: none;
    }
`
const RightBox = styled.div`
     display: flex;
    flex-direction: column;
    z-index: 2;
    padding-left: 500px; /* margin-left 대신 padding 사용 */
    @media screen and (max-width: 1200px) {
       padding: 20px;
    }
`
const Title = styled.h2`
    white-space: pre-line;
    font-size: 50px;
    @media screen and (max-width: 768px) {
        font-size: 24px;
    }
`
const Brand = styled.h2`
    color: #fff;
    font-size: 42px;
    margin-bottom: 20px;
`
const Text = styled.p`
    white-space: pre-line;
    color: #8d7400;
    @media screen and (max-width: 768px) {
        font-size: 12px;
    }
`
const getTitles = (lang) => {
    switch (lang) {
      case 'eng':
        return {
            title: "IS NOW READY TO BE DELIVERED TO THE WORLD",
            brand: "cafe BomBom" ,
            text : "Cafe BomBom started in 2012 as a small cafe in the university district of Daegu, South Korea.\n\n\nWith our unique menu and excellent service, it has very quickly become popular with\nstudents CafeBomBom experiments with different roasts to produce delicious coffee, with\nits scent permeating everywhere and bring warm korean spring energy." ,
            subtext : "80 kinds of drinks and 30 kinds of desserts are available CafeBomBom.\n\n\n The variety and exclusive items in the menu, offordable price and taste that can be\nenjoyed by all ages are the secret to CafeBomBom’s consistent success."
        };
      case 'chn':
        return { 
            title: "将温暖春天的闲暇传达给\n世界的" ,
            brand: "cafe BomBom",
            text : "cafe bom bom从2012年位于韩国、 大邱某大学街的小咖啡店开始,\n以差别化的菜单和只属于我们的特别运营系统受到学生们的喜爱,\n开始逐渐被人们所熟知。\n\n",
            subtext : "为了提供美味的咖啡, 春春独有的研究不断外卖, 立即扩散到中心街,\n我们的香喷喷的咖啡香气不知不觉地渗透到住宅区的各个角落,\n 传递着温暖的春天的能量。"
         };
      case 'jpn':
        return { 
            title: "暖かい春の日の余裕を\n世界各地に伝える", 
            brand: "cafe BomBom" , 
            text : "cafe BomBomは2012年大邱広域市の大学街にある小さなカフェで始まり、\n差別化されたメニューと私たちだけの特別な運営システムで学生たちに愛されて知られ始めた。",
            subtext : "カフェ春春には80種類の飲み物と30種類のデザートが用意されたカフェ春春。\n\n老若男女誰でも楽しめるメニューの多様で独占的なアイテム、\n安い価格と味がカフェ春春の着実な成功の秘訣だ。"
        };
      default:
        return {  title: null , brand: null , text : null, subtext : null};
    }
  }

function Notkor({ lang }) {
    const { title, brand, text, subtext } = getTitles(lang);
  return (
    <Container>
      <Inner>
        <LeftBox></LeftBox>
        <RightBox>
            <Title>{title}</Title>
            <Brand>{brand}</Brand>
            <Text>{text}</Text>
            <Text>{subtext}</Text>
        </RightBox>
      </Inner>
    </Container>
  )
}

export default Notkor
