import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/cobg.png) no-repeat center bottom/cover;
    background-size: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 120px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 5px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: #774126;
`
const SubTitle = styled.h2`
    margin-bottom: 50px;
    color: #666;
    text-align: center;
    @media screen and (max-width:768px){
        font-size: 15px;
    }
`
const TableContainer = styled.div`
    position: relative;
    width: 60%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: url(assets/table.png) no-repeat center bottom / 100% 95%;
  padding: 0 3.5% 40px;

    @media screen and (max-width:768px){
        width: 95%;
        padding: 10px 3.5% 40px;
    }
`;
const HeadImg = styled.img`
    
    width: 20%;
    margin-bottom: 5px;
`
const TableSpan = styled.span`
    align-self: flex-end;
    color: #999;
    letter-spacing: -0.06em;
    margin-bottom: 10px;
    @media screen and (max-width:768px){
    font-size: 9px;
  }
`
const StyledTable = styled.table`
  border-collapse: collapse;
  width: 100%;
  @media screen and (max-width:768px){
    font-size: 10px;
  }
`;

const THead = styled.thead`
  background-color: #f9f9f9;
`;

const TBody = styled.tbody`
  tr:nth-child(even) {
    background-color: #f9f9f9;
  }
`;

const Th = styled.th`
width: calc(100%/5);
  border: 1px solid #ccc;
  padding: 10px;
  text-align: center;
  background-color: #f9f9f9;
  font-weight: bold;
  color: #666;
 
`;

const Td = styled.td`
  border: 1px solid #ccc;
  padding: 10px;
  text-align: center;
  font-weight: ${({ bold }) => (bold ? 'bold' : 'normal')};
  background-color: ${({ bgColor }) => bgColor || 'white'};
  color: ${({ color }) => color || '#666'};
`;

const HighlightTd = styled(Td)`
  background-color: #face00;
  font-weight: bold;
  color: #000;
  border-left: 5px solid #ed3026;
  border-right: 5px solid #ed3026;
 
`;

const SummaryTd = styled(Td)`
  background-color: #774126;
  color: #fff;
  font-weight: bold;
`;

const FooterTd = styled(Td)`
  background-color: #f9f9f9;
  color: #000;
  font-weight: bold;

  &:nth-child(2){
    color: #ed3026;
  }
`;
const Stemp = styled.img`
    position: absolute;
    right: -20px;
    top: -10px;
    width: 80px;
    @media screen and (max-width:768px){
        width: 60px;
    }
`
const BottomSpan = styled.span`
    color: #666;
    align-self: flex-start;
    font-size: 12px;
    @media screen and (max-width:768px){
    font-size: 9px;
  }
`
function Costs() {
  return (
    <Container>
      <Title>타사 대비 <TitleSpan>낮은 창업비용</TitleSpan></Title>
      <SubTitle>매출 상승은 기본! 타사 대비 낮은 창업비로 점주님의 수익을 지켜드립니다.</SubTitle>
      <TableContainer>
        <HeadImg src='assets/tablehead.png'></HeadImg>
        <TableSpan>단위 : 만 원 / 15평 기준 / VAT 별도</TableSpan>
      <StyledTable>
        <THead>
          <tr>
            <Th>항목</Th>
            <HighlightTd style={{borderTop : "5px solid #ed3026"}}>카페봄봄</HighlightTd>
            <Th>A사</Th>
            <Th>B사</Th>
            <Th>C사</Th>
          </tr>
        </THead>
        <TBody>
          <tr>
            <Td>가맹비</Td>
            <HighlightTd style={{textDecoration : "line-through", textDecorationColor : "#ed3026", position : "relative"}}>500<Stemp src='assets/tablestemp.png'  /></HighlightTd>
            <Td>면제</Td>
            <Td>500</Td>
            <Td>500</Td>
          </tr>
          <tr>
            <Td>교육비</Td>
            <HighlightTd style={{textDecoration : "line-through", textDecorationColor : "#ed3026", position : "relative"}}>300<Stemp src='assets/tablestemp.png'  /></HighlightTd>
            <Td>300</Td>
            <Td>200</Td>
            <Td>150</Td>
          </tr>
          <tr>
            <Td>인테리어</Td>
            <HighlightTd>1,620</HighlightTd>
            <Td>1,650</Td>
            <Td>2,200</Td>
            <Td>3,400</Td>
          </tr>
          <tr>
            <Td>간판</Td>
            <HighlightTd>500</HighlightTd>
            <Td>500</Td>
            <Td>550</Td>
            <Td>900</Td>
          </tr>
          <tr>
            <Td>주방기기</Td>
            <HighlightTd>3,160</HighlightTd>
            <Td>3,231</Td>
            <Td>3,200</Td>
            <Td>2,740</Td>
          </tr>
          <tr>
            <Td>오픈 홍보물 및 기타</Td>
            <HighlightTd>100</HighlightTd>
            <Td>136</Td>
            <Td>350</Td>
            <Td>200</Td>
          </tr>
          <tr>
            <SummaryTd>합계</SummaryTd>
            <HighlightTd style={{borderTop : "1px solid #000",borderBottom : "5px solid #ed3026",color : "#ed3026",fontSize: "24px"}}>5,380</HighlightTd>
            <SummaryTd>5,817</SummaryTd>
            <SummaryTd>7,100</SummaryTd>
            <SummaryTd>7,740</SummaryTd>
          </tr>
        </TBody>
        <tfoot>
          <tr  style={{marginTop : "20px"}}>
            <FooterTd>로열티(월)</FooterTd>
            <FooterTd color="#e64c00">15</FooterTd>
            <FooterTd>15</FooterTd>
            <FooterTd>10</FooterTd>
            <FooterTd>15</FooterTd>
          </tr>
        </tfoot>
      </StyledTable>
      <BottomSpan>철거, 냉난방 기타 별도 비용 제외</BottomSpan>
      <BottomSpan>대구·경북·제주 등 일부지역 제외(상세내용 본사 문의)</BottomSpan>
    </TableContainer>
    </Container>
  )
}

export default Costs
