import React, { useState } from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/franchise/intebg.png) no-repeat top left;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0 0 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`

const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`

const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 30px;   
    }
`

const TabBox = styled.div`
    display: flex;
    gap: 10px;
    margin-bottom: 30px;
`

const TabBtn = styled.button`
    padding: 10px 20px;
    font-size: 18px;
    font-weight: ${(props) => props.$isActive ? "bold" : "200"};
    color: ${(props) => props.$isActive ? "#181818" : "#6c6c6c"};
    background-color: ${(props) => props.$isActive ? "#fdda24" : "#fff"};
    border: 1px solid ${(props) => props.$isActive ? "#fdda24" : "#eee"};
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease-in-out;

    &:hover {
        background-color: #fdda24;
        color: #181818;
    }
`

const ContentBox = styled.div`
    width: 100%;
    max-width: 1200px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 20px;
    background-color: #fff;
    border-radius: 12px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    margin-bottom: 50px;
    transition: all 0.3s ease-in-out;
    @media screen and (max-width:768px){
        padding: 0;
    }
`

const ContentTitle = styled.h4`
    font-size: 24px;
    color: #181818;
    margin-bottom: 10px;
    @media screen and (max-width:768px){
        font-size: 18px;
    }
`

const ContentImg = styled.img`
    max-width: 100%;
    border-radius: 8px;
    opacity: ${(props) => props.$isLoading ? 0 : 1};
    transition: opacity 0.3s ease-in-out;
    @media screen and (max-width:768px){
        height: 600px;
    }
`

const Spinner = styled.div`
    border: 4px solid #f3f3f3;
    border-top: 4px solid #fdda24;
    border-radius: 50%;
    width: 40px;
    height: 40px;
    animation: spin 0.8s linear infinite;
    margin: 20px 0;

    @keyframes spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
    }
`

// 탭별로 보여줄 컨텐츠
const contentData = [
    {
        id: 1,
        title: "일반형 매장 소개",
        img: `${process.env.PUBLIC_URL}/assets/franchise/interior1.jpg`
    },
    {
        id: 2,
        title: "고급형 매장 소개",
        img: `${process.env.PUBLIC_URL}/assets/franchise/interior2.jpg`
    }
]

function Interior() {
    const [activeIndex, setActiveIndex] = useState(1);  // 기본으로 첫 번째 탭 활성화
    const [isLoading, setIsLoading] = useState(true);  // 이미지 로딩 상태

    const handleTab = (index) => {
        setActiveIndex(index);
        setIsLoading(true);  // 탭이 바뀌면 다시 로딩 상태로
    }

    const handleImageLoad = () => {
        setIsLoading(false);  // 이미지가 로딩되면 false로 변경
    }

    return (
        <Container>
            <Title>Cafe BOMBOM Interior</Title>
            <SubTitle>다양한 타입의<br /><b>봄봄 인테리어</b></SubTitle>
            <TabBox>
                <TabBtn 
                    onClick={() => handleTab(1)} 
                    $isActive={activeIndex === 1}
                >
                    일반형 매장
                </TabBtn>
                <TabBtn 
                    onClick={() => handleTab(2)} 
                    $isActive={activeIndex === 2}
                >
                    고급형 매장
                </TabBtn>
            </TabBox>
            {contentData.map(({ id, title, img }) => (
                activeIndex === id && (
                    <ContentBox key={id}>
                        <ContentTitle>{title}</ContentTitle>
                        {isLoading && <Spinner />}  {/* 로딩 중일 때 스피너 표시 */}
                        <ContentImg 
                            src={img} 
                            $isLoading={isLoading}
                            onLoad={handleImageLoad}
                        />
                    </ContentBox>
                )
            ))}
        </Container>
    )
}

export default Interior
