import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/recombg.png) no-repeat center bottom/cover;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 120px 0;
    margin: 5px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 5px;
    text-align: center;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: red;
`
const ContantBox = styled.div`
    display: flex;
    justify-content: center;
    align-items: center;
    @media screen and (max-width:768px){
        flex-direction: column;
    }
`
const Contant = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-right: 50px;

    &:last-child{
        margin-right: 0;
    }
    @media screen and (max-width:768px){
        margin-right: 0;
    }
`
const Say = styled.div`
    padding: 10px 20px 20px 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: url(assets/say.png) no-repeat center / cover;
`
const SayText = styled.p`
    font-size: 16px;
    @media screen and (max-width:810px){
        font-size: 12px;
    }
`
const Img = styled.img`
    width: 100px;
    z-index: 2;
`
const Text = styled.p`
    position: relative;
    top: -40px;
    background-color: #fff;
    padding: 60px 20px 20px 20px;
    text-align: center;
    z-index: 1;
    border-radius: 16px;
    box-shadow: 5px 5px 3px rgba(0, 0, 0, 0.3);
    @media screen and (max-width:810px){
        font-size: 12px;
    }
`
const Span = styled.span`
    color: red;
`
const items = [
    {
        id :1,
        say : "다른 직업 하고 싶다...",
        img : "assets/recomimg_1.png",
        text : "매출이 떨어져",
        pointtext : "폐업을 고민하는 사장님"
    },
    {
        id :2,
        say : "돈이 많이 들잖아요...",
        img : "assets/recomimg_2.png",
        text : "업종&브랜드 재창업",
        pointtext : "비용이 부담되는 사장님"
    },
    {
        id :3,
        say : "뭐부터 해야 되죠...?",
        img : "assets/recomimg_3.png",
        text : "열정은 가득하지만",
        pointtext : "창업은 막막한 예비 사장님"
    }
]

function Recommend() {
  return (
    <Container>
      <Title>카페봄봄,<br />이런 사장님께 <TitleSpan>추천</TitleSpan>합니다!</Title>
      <ContantBox>
        {items.map((item)=>(
            <Contant key={item.id}>
                <Say><SayText>{item.say}</SayText></Say>
                <Img src={item.img}/>
                <Text>{item.text}<br /><Span>{item.pointtext}</Span></Text>  
            </Contant>
        ))}
        
      </ContantBox>
    </Container>
  )
}

export default Recommend
