import React from 'react';
import { GoogleMap, LoadScript, Marker } from '@react-google-maps/api';

function Map({ lat, lng, name }) {
  const containerStyle = {
    width: '100%',
    height: '300px',  // 🌸 지도 높이 조절!
    marginBottom: '30px',  // 🌼 간격 조절!
    borderRadius: '10px',  // 🌸 살짝 둥글게!
  };

  const center = { lat, lng };

  return (
    <LoadScript googleMapsApiKey="AIzaSyApCGJZacHE2vFepR2t-uIOhLGMd_djZGc">  {/* 🌸 발급받은 API 키 넣기! */}
      <GoogleMap
        mapContainerStyle={containerStyle}
        center={center}
        zoom={15}
      >
        <Marker position={center} title={name} />  {/* 🌸 마커 표시! */}
      </GoogleMap>
    </LoadScript>
  );
}

export default Map;
