import React from 'react';
import styled from 'styled-components';

const Container = styled.div`
  width: 100%;
  border-radius: 16px;
  background: url(assets/interiorbg.png) no-repeat center / cover;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 120px 0;
  @media screen and (max-width: 768px) {
    padding: 50px 0;
  }
`;
const Bi = styled.p`
  color: #774126;
  border: 1px solid #774126;
  padding: 5px 10px;
  border-radius: 16px;
`;
const Title = styled.h1`
  font-size: 63px;
  margin-bottom: 5px;
  text-align: center;
  color: #face00;
  @media screen and (max-width: 768px) {
    font-size: 25px;
  }
`;
const TitleSpan = styled.span`
  color: #000;
`;
const SubTitle = styled.p`
  font-size: 1.375em;
  margin-bottom: 50px;
  color: #774126;
  text-align: center;
  white-space: pre-line;
  @media screen and (max-width: 768px) {
    font-size: 15px;
  }
`;
const GridContainer = styled.div`
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); 
  grid-auto-rows: 200px; 
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  @media screen and (max-width: 768px) {
    grid-template-columns: repeat(2, 1fr);  
  }
  @media screen and (max-width: 480px) {
    grid-template-columns: 1fr;         
  }
`;

const GridItem = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 8px;  
`;

const Image1 = styled(GridItem)`
  grid-column: span 2;
  grid-row: span 2;
`;

const Image2 = styled(GridItem)`
  grid-column: span 2;
  grid-row: span 1;
`;

const Image3 = styled(GridItem)`
  grid-column: span 2;
  grid-row: span 1;
`;

const SmallImage = styled(GridItem)`
  grid-column: span 1;
  grid-row: span 1;
`;

const Img = styled.img`
  width: 100%;              
  height: 100%;            
  object-fit: cover;        
  transition: transform 0.3s ease;  

  &:hover {
    transform: scale(1.05);  
  }
`;
const getTitles = (lang) => {
  switch (lang) {
    case 'eng':
      return { bi: null, strong: null,title : "CONVEYS THE FEELING OF", titlespan : " WARM SPRING", subTitle: 'New Store Exterior and new logo convey warm spring energy.\n We use a', substrong: "Specialised interior system to optimize the store layout for efficient operation" };
    case 'chn':
      return { title: null , titlespan: "传递温暖春天的感觉。", subTitle: '新店面外观、新标志传递温暖春意。\n采用专用的内部系统优化门店布局，实现高效运行。' };
    case 'jpn':
      return { title: null , titlespan: "春のように明るく暖かいインテリア", subTitle: '新しい店舗の外観と新しいロゴは暖かい春の気配をお届けします。\n専門化されたシステムを通じて店舗形態に最適化された構造で設計し、\n効率的な店舗運営をサポートします。' };
    default:
      return { bi: '변경된 BI로 ', strong: "NEW 인테리어",title : "봄처럼 밝고 따뜻한", titlespan : " 느낌의 인테리어", subTitle: '새롭게 변경된 BI를 살려 봄처럼 밝고 따뜻한 느낌의 인테리어를 느끼실 수 있습니다.\n외·내부 또한', substrong: "전문화된 시스템을 통해 매장 형태에 최적화된 구조로 설계하여 효율적인 매장 운영 을 도와드립니다." };
  }
}

function Interior({ lang }) {
  const { bi, strong, title, titlespan, subTitle, substrong } = getTitles(lang);
  return (
    <Container>
      {/* 🌸 bi가 있을 때만 렌더링 */}
      {bi && <Bi>{bi}<strong>{strong}</strong></Bi>}
      
      {/* 🌸 title이나 titlespan 중 하나라도 있을 때 렌더링 */}
      {(title || titlespan) && (
        <Title>
          {title && title}  {/* 🌸 title이 있으면 출력 */}
          {titlespan && <TitleSpan>{titlespan}</TitleSpan>}  {/* 🌸 titlespan이 있으면 출력 */}
        </Title>
      )}
      
      {/* 🌸 subTitle이 있을 때만 렌더링 */}
      {subTitle && <SubTitle>{subTitle} <strong>{substrong}</strong></SubTitle>}
      
      <GridContainer>
        <Image1>
          <Img src="assets/interior_1.png" alt="interior_1" />
        </Image1>
        <Image2>
          <Img src="assets/interior_2.png" alt="interior_2" />
        </Image2>
        <Image3>
          <Img src="assets/interior_3.png" alt="interior_3" />
        </Image3>
        {[4, 5, 6, 7].map((num) => (
          <SmallImage key={num}>
            <Img src={`assets/interior_${num}.png`} alt={`interior_${num}`} />
          </SmallImage>
        ))}
      </GridContainer>
    </Container>
  );
}


export default Interior;
