import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Pagination, Autoplay } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";
import styled from "styled-components";

const BannerContainer = styled.div`
  width: 100%;
  overflow: hidden;
  border-radius: 16px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
`;

const StyledSwiper = styled(Swiper)`
  border-radius: 16px;

  .swiper-pagination-bullet {
    background: #ffffff;
    opacity: 0.6;
  }

  .swiper-pagination-bullet-active {
    background: #000;
    opacity: 1;
  }
`;

const BannerImage = styled.img`
  width: 100%;
`;

const getBannerImages = (lang) => {
  switch (lang) {
    case "eng":
      return Array.from({ length: 2 }, (_, i) => `assets/eng/mainbanner${i + 1}.jpg`);
    case "chn":
      return Array.from({ length: 3 }, (_, i) => `assets/chn/mainbanner${i + 1}.jpg`);
    case "jpn":
      return Array.from({ length: 3 }, (_, i) => `assets/jpn/mainbanner${i + 1}.jpg`);
    default:
      return Array.from({ length: 10 }, (_, i) => `assets/kor/mainbanner${i + 1}.jpg`);
  }
};

const MainBanner = ({ lang }) => {
  const images = getBannerImages(lang);  

  return (
    <BannerContainer>
      <StyledSwiper
        modules={[Navigation, Pagination, Autoplay]}
        spaceBetween={10}
        slidesPerView={1}
  
        pagination={{ clickable: true }}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        loop={true}
      >
        {images.map((src, index) => (
          <SwiperSlide key={index}>
            <BannerImage src={src} alt={`Banner ${index + 1}`} />
          </SwiperSlide>
        ))}
      </StyledSwiper>
    </BannerContainer>
  );
};

export default MainBanner;
