import React from 'react'
import RegionMap from './RegionMap'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    display: flex;
    background: url(assets/storebg.png)no-repeat top ;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 50px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`
const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`
function Store() {
  return (
    <Container>
        <Title>Cafe BOMBOM Store</Title>
        <SubTitle>봄봄 <b>매장찾기</b></SubTitle>
      <RegionMap />
    </Container>
  )
}

export default Store
