import React from 'react'
import styled, {keyframes} from 'styled-components'

const slideInLeft = keyframes`
  from {
    opacity: 0;
    transform: translateX(-50px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
`;

const slideInBottom = keyframes`
  from {
    opacity: 0;
    transform: translateY(50px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const Container = styled.div`
    width: 100%;
    background: url(assets/openbg.png);
    display: flex;
    flex-direction: column;
    border-radius: 16px;
    overflow: hidden;
    padding: 100px 50px;

    @media screen and (max-width:768px) {
        padding: 50px 10px;
    }
`
const TitleBox = styled.div`
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
`
const TitleP = styled.p`
    font-size: 22px;
    color: #222;
`
const Title = styled.h2`
    font-size: 49px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: red;
`
const Contants = styled.div`
    display: flex;
    margin-top: 20px;
`
const LeftBox = styled.div`
    width: 50%;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    padding-right: 100px;
    animation: ${slideInLeft} 0.8s ease-out;
    @media screen and (max-width:900px) {
        padding-right: 0;
    }
    @media screen and (max-width:670px) {
        width: 100%;
        align-items: center;
    }
    
`
const LeftTitle = styled.h1`
    position: relative;
    top: 10px;
    font-size: 20px;
    text-align: center;
    background: #000;
    color: #fff;
    padding: 20px;
    border-radius: 10px;
    width: 300px;
`
const LeftUl = styled.ul`
    width: 300px;
    background-color: #fff;
    padding: 20px;
    border-radius: 10px;
`
const LeftLi = styled.li`
    margin: 10px;
`
const LeftImg = styled.img`
    position: absolute;
    top: -8px;
    left: -8px;
`
const RightBox = styled.div`
    width: 50%;
    display: flex;
    animation: ${slideInBottom} 0.8s ease-out;
    @media screen and (max-width:970px) {
       justify-content: center;
       align-items: center;
    }
    @media screen and (max-width:670px) {
        display: none;
    }

`
const RightItem = styled.div`
    position: relative;
`
const MapImg = styled.img`
  width: 100%;
`
const Stemp = styled.img`
    width: 100%;
    position: absolute;
    right: 0;
    top: 0;
   
`
const franchise = ["광주 송정도산점","서대구 반도유보라센텀점","동대구 센텀점","공주대학교점","부산 화명점","제주 아라점","만평점","시흥 배곧호반써밋점","순천 금당점","여수 무선점","나주역점","파주 운정한울마을점","삼익뉴타운점","울진 죽변점"]
function Open() {
  return (
    <Container>
    <TitleBox>
        <TitleP>카페봄봄의</TitleP>
        <Title>가맹점 <TitleSpan>오픈현황</TitleSpan></Title>
    </TitleBox>
    <Contants>
        <LeftBox>
            <LeftTitle>
                신규 오픈 가맹점
                <LeftImg src='assets/new.png'></LeftImg>
            </LeftTitle>
            <LeftUl>
                {franchise.map((item,index)=>(
                    <LeftLi key={index}>{item}</LeftLi>
                ))}
            </LeftUl>
        </LeftBox>
        <RightBox>
            <RightItem>
            <MapImg src='assets/map.gif'></MapImg>
            <Stemp src='assets/stemp.png'></Stemp>
            </RightItem>
        </RightBox>
    </Contants>
    </Container>
  )
}

export default Open
