import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/mkbg.png) no-repeat center bottom/cover;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 120px 0;
    margin: 5px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 5px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: red;
`
const SubTitle = styled.h2`
    margin-bottom: 50px;
    color: #666;
    text-align: center;
    @media screen and (max-width:768px){
        font-size: 15px;
    }
`
const Ul = styled.ul`
    display: flex;
`
const Li = styled.li`
   border-radius: 6em;
    width: 6em;
    height: 6em;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #fff;
    border: 1px solid #ddd;
    margin: 0.5em;

    &:hover {
        background-color: #eb615a;
        border-color: #eb615a;
        color: #fff;

        a{
            filter: brightness(200);
        }
    }
`
const A = styled.a`
    text-align: center;
    font-size: 14px;
`
const Img = styled.img`
    width: 35%;
`
function Marketing() {
  return (
    <Container>
      <Title>트렌디한 <TitleSpan>본사 마케팅</TitleSpan></Title>
      <SubTitle>다양한 홍보마케팅으로 카페봄봄의 브랜드 인지도 상승에 도움을 드립니다.</SubTitle>
      <Ul>
        <Li>
        <A href='https://www.youtube.com/@cafebombom_official' target='_blank'>
            <Img src='assets/mk_youtube.png'></Img><br />
            유튜브
            </A>
        </Li>
        <Li>
        <A href='https://blog.naver.com/cafe-bombom' target='_blank'>
            <Img src='assets/mk_blog.png'></Img><br />
            블로그
            </A>
        </Li>
        <Li>
            <A href='https://www.instagram.com/cafebombom_official/' target='_blank'>
            <Img src='assets/mk_instar.png'></Img><br />
            인스타그램
            </A>
        </Li>
      </Ul>
    </Container>
  )
}

export default Marketing
