import React, { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import tableItem from './TableItem';  // 🌸 기존 데이터 임포트!
import styled from 'styled-components';
import { Map, MapMarker } from 'react-kakao-maps-sdk';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding-top: 6.25em;
`;

const TitleBox = styled.div`
    width: 100%;
    height: 400px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 30px;
    background: url(assets/brandbg.png) no-repeat center / cover;
    padding: 20px;
    margin-bottom: 5px;
    border-radius: 10px;
    color: #fff;
    @media screen and (max-width:768px){
      height: 200px;
    }
`;

const Title = styled.h2`
    font-size: 50px;
    @media screen and (max-width:768px){
      font-size: 30px;
    }
`;

const SubTitle = styled.p`
    font-size: 20px;
    color: #fff;
    text-align: center;
    @media screen and (max-width:768px){
      font-size: 18px;
    }
`;

const SubTitleSpan = styled.span`
    color: #fdda24;
    font-weight: bold;
`;

const Title2 = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
    margin-top: 50px;
`
const SubTitle2 = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`
const Contant = styled.div`
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    max-width: 1400px;
    gap: 30px;
    padding: 50px 0;
    @media screen and (max-width:800px){
        flex-direction: column;
    }
`
const ImgBox = styled.div`
     @media screen and (max-width:800px){
        width: 100%;
    }
` 
const Img = styled.img`
    width: 100%;
    height: 400px;
`
const TableBox = styled.div`

`
const Table = styled.table`
    border-top: 2px solid #333;
    border-collapse: collapse;
    height: 400px;
`
const Th = styled.th`
    padding: 15px;
    font-size: 14px;
    background: #f5f5f5;
    border-bottom: 1px solid #e5e5e5;
    text-align: center;
    color: #181818;
    width: 200px;
`
const Td = styled.td`
padding: 15px;
    border-bottom: 1px solid #e5e5e5;
    font-size: 14px;
    color: #585858;
`
const MapBox = styled.div`
  width: 100%;
  max-width: 800px;
  margin-top: 30px;
`
const KakaoLink = styled.a`
        background-color: #fdda24;
        padding: 5px 10px;
        color: #000;
        border-radius: 5px;
        text-decoration: none;
        font-weight: bold;

        &:hover {
            background-color: #000;
            color: #fff;
        }
`
const BackBtn = styled.button`
    font-weight: bold;
    background-color: #fdda24;
    color: #000;
    padding: 10px;
    margin: 50px 0;
    border-radius: 16px;

    &:hover {
        background-color: #000;
        color: #fff;
    }
`
function View() {
     useEffect(() => {
        // 🌟 Kakao API 로딩이 끝나면 초기화!
        if (window.kakao && window.kakao.maps) {
          window.kakao.maps.load(() => {
          });
        }
      }, []);
  const { id } = useParams();  // 🌸 URL의 id 가져오기!
  const navigate = useNavigate();
  
  // 🌼 ID에 맞는 데이터 찾기!
  const item = tableItem.find((el) => el.id === parseInt(id));

  // 🌸 데이터가 없을 때 처리!
  if (!item) {
    return (
      <div style={{ textAlign: 'center', marginTop: '50px' }}>
        <h2>해당 매장을 찾을 수 없어요! 😢</h2>
        <button onClick={() => navigate(-1)}>돌아가기</button>  {/* 💖 뒤로가기 버튼! */}
      </div>
    );
  }

  return (
    <Container>
         <TitleBox>
        <Title>매장안내</Title>
        <SubTitle>차별화를 추구하여 보다 성장하는 <SubTitleSpan>Cafe 봄봄</SubTitleSpan></SubTitle>
      </TitleBox>
      <Title2>Cafe BOMBOM Store</Title2>
      <SubTitle2>봄봄 <b>매장찾기</b></SubTitle2>
      <Contant>
        <ImgBox>
        <Img src={item.img  || `${process.env.PUBLIC_URL}/assets/store/default.png`} />
        </ImgBox>
        <TableBox>
            <Table>
                <tbody>
                    <tr>
                        <Th>가맹점명</Th>
                        <Td>{item.name}</Td>
                    </tr>
                    <tr>
                        <Th>주소</Th>
                        <Td>{item.address}</Td>
                    </tr>
                    <tr>
                        <Th>전화번호</Th>
                        <Td>{item.tel}</Td>
                    </tr>
                    <tr>
                        <Th>영업시간</Th>
                        <Td>{item.time}</Td>
                    </tr>
                    <tr>
                        <Th>서비스</Th>
                        <Td>와이파이</Td>
                    </tr>
                </tbody>
            </Table>
        </TableBox>
      
      </Contant>
       <MapBox>
          <Map
            center={{ lat: item.lat, lng: item.lng }}  // 대구광역시 중구 동덕로 125 좌표
            style={{ width: "100%", height: "500px" }} 
            level={3}
          >
            <MapMarker position={{ lat: item.lat, lng: item.lng }}>
              <div style={{ padding: "5px 0 5px 17px", color: "#000", fontSize : "12px", fontWeight : "bold"  }}>{item.address}</div>
            </MapMarker>
          </Map>
          <div style={{ textAlign: 'right', marginTop: '10px' }}>
    <KakaoLink
      href={`https://map.kakao.com/link/to/${item.name},${item.lat},${item.lng}`}
      target="_blank"  // 🌼 새 창에서 열리도록!
      rel="noopener noreferrer"  // 🌼 보안 설정!
    >
      Kakao Map에서 길찾기
    </KakaoLink>
  </div>
  <p style={{textAlign: "center", fontSize : "12px",marginTop : "20px"}}>** 운영시간은 매장마다 상이할 수 있습니다.</p>
          </MapBox>
      <BackBtn onClick={() => navigate(-1)}>돌아가기</BackBtn> 
    </Container>
  );
}

export default View;
