import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
  background-color: #161719;
  padding: 50px;
  border-radius: 16px;
  margin-top: 3px;
  text-align: center;  // 🌸 가운데 정렬
  @media (max-width: 768px) {
    padding: 20px;
  }
`
const Inner = styled.div`
   max-width: 1400px;
   margin: 0 auto;
   display: flex;
   flex-direction: column;
   align-items: center;
`
const InfoTitle = styled.strong`
  width: 100%;
  font-size: 13px;
  color: #fff;
  text-align: left;
`
const Contants = styled.div`
  position: relative;
  margin-top: 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  @media (max-width: 768px) {
   flex-direction: column;
  }
`
const Ul = styled.ul`
  display: flex;
  flex-wrap: wrap;
  color: #a09f9f;
  width: 50%;
  @media (max-width: 768px) {
    width: 100%;
  }
`
const Li = styled.li`
  font-size: 13px;
  margin-right: 25px;
  margin-bottom: 5px;
`
const Logo = styled.img`
  cursor: pointer;
  width: ${({ lang }) => (lang === "kor" ? "200px" : "100px")}; 
  

  content: ${({ lang }) => 
    lang === "kor" 
      ? `url(${process.env.PUBLIC_URL}/assets/logo.png)`
      : `url(${process.env.PUBLIC_URL}/assets/logo.svg)`}; 

  @media (max-width: 768px) {
    content: ${({ lang }) => 
      lang === "kor" 
        ? `url(${process.env.PUBLIC_URL}/assets/logo_m.png)` 
        : `url(${process.env.PUBLIC_URL}/assets/logo.svg)`}; 
    width: 100px;  
    position: absolute;
    right: 10px;
    top: -30px;
  }
`;

const CopyrightText = styled.p`
  font-size: 12px;
  color: #a09f9f;
  margin-top: 10px;
`

function Footer({ lang }) {  
  // 🌸 🛠️ 언어에 따른 로고 경로 설정!
  const logoSrc = lang === "kor" 
  ? `${process.env.PUBLIC_URL}/assets/logo.png` 
  : `${process.env.PUBLIC_URL}/assets/${lang}/logo.svg`;

  
  return (
    <Container>
      {lang === "kor" ? (
        <Inner>
          <InfoTitle>COMPANY INFO</InfoTitle>
          <Contants>
            <Ul>
              <Li>카페봄봄</Li>
              <Li>대표 이 승 은</Li>
              <Li>사업자등록번호 805-81-01591</Li>
              <Li>본사 : 대구광역시 중구 동덕로 125(삼덕동 2가 101-1번지) 5, 6층</Li>
              <Li>서울 지사 : 서울특별시 금천구 가산디지털1로 128, 18층 1808호(가산동, 에스티엑스브이타워)</Li>
              <Li>대표번호 053-756-7272</Li>
              <Li>가맹문의 070-7817-1100</Li>
              <Li>팩스 053-756-7373</Li>
              <Li>이메일 cafebombom2019@naver.com</Li>
            </Ul>
            <Logo src={logoSrc}></Logo>  
          </Contants>
        </Inner>
      ) : (
        // 🌸 🛠️ kor이 아니면 이 부분만 보여주기!
        <>
          <img src={`${process.env.PUBLIC_URL}/assets/lanfooterlogo.png`} alt="Logo" style={{ marginBottom: "10px" }} />
          <CopyrightText>COPYRIGHT (C) BOMBOM. ALL RIGHT RESERVED.</CopyrightText>
        </>
      )}
    </Container>
  )
}

export default Footer
