import React, { useState } from 'react'
import styled from 'styled-components'
import Company from './Company'
import Education from './Education'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(/assets/storybg.png) no-repeat left top;
    background-size: auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 50px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`
const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`
const ToggleBox = styled.div`
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 50px;
    flex-wrap: wrap;
    margin-bottom: 30px;
    @media screen and (max-width:768px){
        gap: 20px;
    }
`
const ToggleBtn = styled.button`
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 150px;
    height: 150px;
    background-color: ${props => (props.$active ? '#fdda24' : '#fff')};
    border: 1px solid #ccc;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    transition: all 0.3s ease;
    cursor: pointer;

    &:hover {
        box-shadow: 0 6px 10px rgba(0, 0, 0, 0.2);
    }
`
const BtnImg = styled.img`
    width: 50px;
    height: 50px;
    margin-bottom: 10px;
    object-fit: contain;
`
const BtnText = styled.p`
    font-size: 14px;
    font-weight: 600;
    color: ${props => (props.$active ? '#fff' : '#333')};
    margin-bottom: 5px;
`
const BtnTitle = styled.h3`
    font-size: 18px;
    font-weight: 700;
    color: #181818;
`

const ContentBox = styled.div`
    width: 100%;
    max-width: 1400px;
    padding: 80px 20px;
    border: 1px solid #ccc;
    border-radius: 10px;
    background-color: #fff;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    text-align: center;
    transition: all 0.3s ease;
`

const contents = {
    company: <Company />,
    education: <Education />
}

function Philosophy() {
    const [active, setActive] = useState('company');

    const handleClick = (type) => {
        setActive(type);
    }

    return (
        <Container>
            <Title>Cafe BOMBOM</Title>
            <SubTitle><b>Cafe 봄봄</b><br />브랜드를 소개합니다</SubTitle>
            <ToggleBox>
                <ToggleBtn 
                    $active={active === 'company'} 
                    onClick={() => handleClick('company')}
                >
                    <BtnImg src={`${process.env.PUBLIC_URL}/assets/btnicon1.png`} />
                    <BtnText $active={active === 'company'}>COMPANY</BtnText>
                    <BtnTitle>카페봄봄</BtnTitle>
                </ToggleBtn>
                <ToggleBtn 
                    $active={active === 'education'} 
                    onClick={() => handleClick('education')}
                >
                    <BtnImg src={`${process.env.PUBLIC_URL}/assets/btnicon2.png`} />
                    <BtnText $active={active === 'education'} >Education</BtnText>
                    <BtnTitle>교육장</BtnTitle>
                </ToggleBtn>
            </ToggleBox>

            {active && (
                <ContentBox>
                    {contents[active]}
                </ContentBox>
            )}
        </Container>
    )
}

export default Philosophy
