import { createGlobalStyle } from "styled-components";

const GlobalStyles = createGlobalStyle`
  /* 기본 리셋 */
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  /* 기본 폰트 및 배경 설정 */
  a {
    text-decoration: none;
    color: inherit;
  }

  ul, li {
    list-style: none;
  }

  button {
    cursor: pointer;
    border: none;
    outline: none;
  }
`;

export default GlobalStyles;
