import React from 'react'
import styled from 'styled-components'
import Menu from '../components/menu/Menu'
const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding-top: 6.25em;
`;

const TitleBox = styled.div`
    width: 100%;
    height: 400px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 30px;
    background: url(assets/brandbg.png) no-repeat center / cover;
    padding: 20px;
    margin-bottom: 5px;
    border-radius: 10px;
    color: #fff;
    @media screen and (max-width:768px){
      height: 200px;
    }
`;

const Title = styled.h2`
    font-size: 50px;
    @media screen and (max-width:768px){
      font-size: 30px;
    }
`;

const SubTitle = styled.p`
    font-size: 20px;
    color: #fff;
    text-align: center;
    @media screen and (max-width:768px){
      font-size: 18px;
    }
`;

const SubTitleSpan = styled.span`
    color: #fdda24;
    font-weight: bold;
`; 

function MenuPage() {
  return (
    <Container>
    <TitleBox>
       <Title>메뉴소개</Title>
        <SubTitle>차별화를 추구하여 보다 성장하는 <SubTitleSpan>Cafe 봄봄</SubTitleSpan></SubTitle>
      </TitleBox>
      <Menu />
      </Container>
  )
}

export default MenuPage
