import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background-size: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 100px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 10px;
`
const SubTitle = styled.h3`
    font-size: 30px;
    font-weight: 200;
    color: #181818;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 24px;   
    }
`
const ContantBox = styled.div`
    width: 100%;
    max-width: 1400px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    @media screen and (max-width:1415px){
      justify-content: center;
    }
`
const ImgBox = styled.div`
  align-self: flex-start;
  height: 100%;
`
const Img = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
`

const HistoryBox = styled.div`

`

const HisUl = styled.ul`
  display: flex;
  flex-direction: column;
  padding: 10px;
`

const HisLi = styled.li`
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  padding: 30px 0;
  border-bottom: 1px solid #ccc;
  gap: 50px;
  @media screen and (max-width:768px) {
    gap: 10px;
  }
`

const YearSpan = styled.span`
  font-weight: bold;
  font-size: 40px;
  margin-bottom: 10px;
  color: ${props => props.color || '#000'};
  @media screen and (max-width:768px) {
    font-size: 30px;
  }
`

const HisOl = styled.ol`
  margin-left: 20px;
  
  li {
    margin-bottom: 5px;
  }
`

const MonthSpan = styled.span`
  margin-right: 10px;
  font-weight: bold;
  @media screen and (max-width:768px) {
    font-size: 12px;
  }
`

const Text = styled.p`
  display: inline;
  color: #9b9b9b;
  @media screen and (max-width:768px) {
    font-size: 12px;
  }
`
const LogoImg = styled.img`
  
`
