function History() {
  return (
    <Container>
      <Title>Cafe BOMBOM History</Title>
      <SubTitle><b>한 단계씩 성장하는</b><br />Cafe 봄봄</SubTitle>
      <ContantBox>
        <ImgBox>
        <Img src={`${process.env.PUBLIC_URL}/assets/history2.png`} />
        </ImgBox>
        <HistoryBox>
          <HisUl>
            {historylist.map((item) => (
              <HisLi key={item.id}>
                <YearSpan color={item.color}>{item.year}</YearSpan>
                <HisOl>
                  {item.month.map((month, idx) => (
                    <li key={idx} style={{display : "flex",alignItems : "center",gap : "10px"}}>
                     {month && <MonthSpan>{month}</MonthSpan>}
                      <Text>{item.text[idx]}</Text>
                      {item.logo && <LogoImg src={item.logo} alt="로고" />}
                    </li>
                  ))}
                </HisOl>
              </HisLi>
            ))}
          </HisUl>
        </HistoryBox>
      </ContantBox>
    </Container>
  )
}

export default History
