import React from 'react';
import styled from 'styled-components';

const Container = styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`;
const LoginBox = styled.div`
     width: 350px;
    border: 1px solid #ddd;
    background-color: #fff;
    display: flex;
    flex-direction: column;
    align-items: center;

`
const TabContainer = styled.div`
    width: 100%;
    display: flex;
`;

const Tab = styled.button`
    flex: 1;
    padding: 20px;
    font-size: 0.75em;
    font-weight: bold;
    background: ${({ active }) => (active ? '#fff' : '#f5f5f5')};
    border: none;
    cursor: pointer;
`;

const Form = styled.form`
    width: 100%;
    display: flex;
    flex-direction: column;
    margin-top: 20px;
    padding: 10px 20px;
`;

const Input = styled.input`
    width: calc(100% - 20px);
    padding: 12px;
    margin: 5px 10px;
    border: 1px solid #ddd;
    border-radius: 3px;
    position: relative;
`;

const RequiredMark = styled.span`
    color: red;
    position: absolute;
    right: 20px;
    top: 5px;
    font-size: 14px;
`;

const InputWrapper = styled.div`
    position: relative;
    display: flex;
    flex-direction: column;
`;

const LoginButton = styled.button`
    width: calc(100% - 20px);
    padding: 12px;
    margin: 10px 10px;
    font-size: 16px;
    font-weight: bold;
    border: 1px solid black;
    background-color: #f5f5f5;
    cursor: pointer;
    border-radius: 3px;

    &:hover {
        background-color: #e0e0e0;
    }
`;

const OptionContainer = styled.div`
    width: calc(100% - 20px);
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 10px 10px;
    font-size: 14px;
    color: #555;
`;

const CheckboxLabel = styled.label`
    display: flex;
    align-items: center;
    gap: 5px;
    cursor: pointer;
`;

const Link = styled.a`
    color: #3a8afd;
    border: 1px solid #d5d9dd;
    padding: 5px;
    border-radius: 5px;
    text-decoration: none;
    cursor: pointer;

    &:hover {
        text-decoration: underline;
    }
`;

function Login() {
    return (
        <Container>
            <LoginBox>
            {/* 로그인 / 회원가입 탭 */}
            <TabContainer>
                <Tab active>로그인</Tab>
                <Tab>회원가입</Tab>
            </TabContainer>

            {/* 로그인 폼 */}
            <Form>
                <InputWrapper>
                    <Input type="text" placeholder="아이디" required />
                    <RequiredMark>*</RequiredMark>
                </InputWrapper>

                <InputWrapper>
                    <Input type="password" placeholder="비밀번호" required />
                    <RequiredMark>*</RequiredMark>
                </InputWrapper>

                <LoginButton type="submit">로그인</LoginButton>

                <OptionContainer>
                    <CheckboxLabel>
                        <input type="checkbox" />
                        자동로그인
                    </CheckboxLabel>
                    <Link href="#">정보찾기</Link>
                </OptionContainer>
            </Form>
            </LoginBox>
        </Container>
    );
}

export default Login;
