import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 30px;
`
const Title = styled.h2`
    font-weight: 500;
`
const Text = styled.p`
    font-size: 15px;
    line-height: 25px;

    @media screen and (max-width:768px){
        font-size: 12px;
    }
`
const Img = styled.img`
    width: 100%;
    max-width: 800px;
`

function Education() {
  return (
    <Container>
    <Title>교육장 소개</Title>
    <Text>Cafe 봄봄은 Take-Out 전문 카페로 출발하였습니다.<br />대학가에서 차별화 된 메뉴와 특별한 운영시스템으로 많은 학생들의 사랑을 받았습니다.<br />Take-Out 시장이 커지면서 Cafe 봄봄은 대학가를 넘어 중심가, 주택가 곳곳에서 한층 더 성장했습니다.</Text>
    <Img src={`${process.env.PUBLIC_URL}/assets/ph2.png`} />
    <Img src={`${process.env.PUBLIC_URL}/assets/ph3.png`} />
  </Container>
  )
}

export default Education
