import React from 'react';
import styled from 'styled-components';
import MapComponent from './Map';

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 50px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`;

const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
    margin-top: 50px;
`;

const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`;

const ConTitle = styled.p`
    font-size: 19px;
    color: #9b9b9b;
    line-height: 36px;
    letter-spacing: -1px;
`;

const ConSpan = styled.span`
    color: #181818;
    font-weight: 600;
    display: inline-block;
    margin-right: 12px;
`;

const MapBox = styled.div`
    width: 90%;
    max-width: 600px;
    margin-bottom: 50px;
    border-radius: 10px;
    overflow: hidden;  // 🌸 지도 넘치지 않게!
`;

function Overseas() {
  return (
    <Container>
      <Title>Cafe BomBom, Singapore</Title>
      <SubTitle>카페봄봄 <b>싱가포르 1호점</b></SubTitle>
      <ConTitle><ConSpan>주소</ConSpan>Tampines Central 1, #04-14 10, Singapore 529536</ConTitle>
      <ConTitle><ConSpan>운영시간</ConSpan>10:30am to 9:30pm</ConTitle>
      <MapBox>
        <MapComponent lat={1.352083} lng={103.819836} name="싱가포르 1호점" />  {/* 🌸 지도 추가! */}
      </MapBox>

      <Title>Cafe BomBom, Carrollton</Title>
      <SubTitle>카페봄봄 <b>Carrollton점</b></SubTitle>
      <ConTitle><ConSpan>주소</ConSpan>2625 Old Denton Rd #225, Carrollton, TX 75007 CAFE BOMBOM</ConTitle>
      <ConTitle><ConSpan>운영시간</ConSpan>09:00-20:00(Sun-Thu) 09:00-20:30(Fri-Sat)</ConTitle>
      <MapBox>
        <MapComponent lat={32.968601} lng={-96.883243} name="Carrollton점" />  {/* 🌸 지도 추가! */}
      </MapBox>

      <Title>Cafe BomBom, Singapore</Title>
      <SubTitle>카페봄봄 <b>싱가포르 2호점</b></SubTitle>
      <ConTitle><ConSpan>주소</ConSpan>7 Jalan Klapa Singapore 199319</ConTitle>
      <ConTitle><ConSpan>운영시간</ConSpan>11:30-15:00 / 17:00-22:30</ConTitle>
      <MapBox>
        <MapComponent lat={1.300858} lng={103.856891} name="싱가포르 2호점" />  {/* 🌸 지도 추가! */}
      </MapBox>

      <Title>Cafe BomBom, SM City Fairview</Title>
      <SubTitle>카페봄봄 <b>SM City Fairview점</b></SubTitle>
      <ConTitle><ConSpan>주소</ConSpan>Lower Ground Level, Parkway, SM City Fairview, 2 Quirino Hwy, Novaliches, Quezon City, Metro Manila, Philippines</ConTitle>
      <ConTitle><ConSpan>운영시간</ConSpan>10:00-22:00(Everyday)</ConTitle>
      <MapBox>
        <MapComponent lat={14.731403} lng={121.060822} name="SM City Fairview점" />  {/* 🌸 지도 추가! */}
      </MapBox>
    </Container>
  );
}

export default Overseas;
