const getTitles = (lang) => {
  switch (lang) {
    case 'eng':
      return { title: 'EXCELLENCE  ', titlespan: "IN TASTE", subTitle: 'Our coffee has a rich and savoury flavour, as it is roasted using the Top 1% specialty blended coffee beans. The menu has a wide variety of items with 80 different drinks and 30 desserts. In addition, our exclusive ever- changing Signature line sets a trend in taste.' };
    case 'chn':
      return { title: 'cafe BomBom ', titlespan: "招牌菜", subTitle: '我们的咖啡是使用前1%的特产混合咖啡豆炒的，味道很浓，很香。 菜单由80种不同的饮料和30种甜点组成。 另外,不断变化的本公司独家"招牌菜"正在形成味道趋势。' };
    case 'jpn':
      return { title: 'cafe BomBom ', titlespan: "のシグネチャーメニュー", subTitle: '当コーヒーは上位1%の特産品ブレンドコーヒー豆を使用して炒め、豊かで香ばしい味がします。 メニューは80種類の様々な飲み物と30種類のデザートで構成されています。 また、絶えず変化する当社の独占的な"シグネチャー"ラインは味のトレンドを形成します。' };
    default:
      return { title: '카페봄봄 ', titlespan: "시그니처 메뉴", subTitle: '깐깐하고, 세밀한 기준으로 디자인한 카페봄봄의 메뉴를 소개합니다.' };
  }
}

function Slide({ lang }) {
  const slideData = getSlideData(lang);  // 🌸 🛠️ 언어별 슬라이드 데이터 가져오기
  const { title, titlespan , subTitle } = getTitles(lang);
  if (slideData.length === 0) return null;  
  return (
    <Container>
    <Title>{title}<TitleSpan>{titlespan}</TitleSpan></Title>
    <SubTitle>{subTitle}</SubTitle>
  <StyledSwiper
    modules={[Autoplay]}
    autoplay={{ delay: 3000 }}
    loop
    slidesPerView="auto" 
    breakpoints={{
        0: { slidesPerView: 1 },  
        640 : { slidesPerView: 2 },
        1024: { slidesPerView: 3 },  
        1500: { slidesPerView: 5 }
      }}
    speed={1500}
  >
    {slideData.map((item, index) => (
      <SwiperSlide key={index}>
        <SlideItem>
          <SlideImage src={item.img} alt={`slide_${index + 1}`} />
          <SlideText>{item.text}</SlideText>
        </SlideItem>
      </SwiperSlide>
    ))}
  </StyledSwiper>
</Container>
  )
}

export default Slide
