import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    background: url(assets/ccbg.png);
    padding: 120px 0;
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 5px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: #fff;
`
const SubTitle = styled.h2`
    margin-bottom: 50px;
    color: #f6b4b1;
    text-align: center;
    @media screen and (max-width:768px){
        font-size: 15px;
    }
`
const Contant = styled.div`
    position: relative;
    max-width: 1400px;
`
const Ul = styled.ul`
    display: flex;
    flex-wrap: wrap;
`
const Li = styled.li`
    width: 48%;
    padding: 4em 0;
    margin: 1%;
    background-color: #fff;
    border-radius: 1rem;
    box-shadow: 5px 5px 0 rgba(0,0,0,0.3);
    border: 1px solid #752420;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    @media screen and (max-width:768px) {
        padding: 5px 0;
    }
`
const Icon = styled.img`
    
`
const ConTitle = styled.h2`
    color: #ea483f;
    padding: 20px 0;
    font-size: 37px;
    @media screen and (max-width:768px) {
        font-size: 16px;
    }
`
const ConText = styled.p`
    font-size: 1em;
    color: #666;
    white-space: pre-line;
    letter-spacing: -0.06em;
    @media screen and (max-width:768px) {
        font-size: 12px;
        line-height: 15px;
    }
`
const LogoBox = styled.div`
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%,-50%);
    @media screen and (max-width:500px) {
        top: 54%;
    }
`
const Logo = styled.img`
     @media screen and (max-width:768px) {
        width: 100px;
        height: 100px;
    }
    @media screen and (max-width:500px) {
        width: 50px;
        height: 50px;
    }
`
const items = [
    {
        id : 1,
        icon : "assets/cc_icon1.png",
        title : "전문화된 교육 시스템",
        text :  "일주일 간 메뉴 제조부터 시스템 교육,\n판매 시뮬레이션 등 전문적인 모든 과정을\nstep-by-step으로 알려드립니다."
    },
    {
        id : 2,
        icon : "assets/cc_icon2.png",
        title : "체계적인 가맹점 관리 시스템",
        text :  "매장 운영 시스템을 통해 문의,요청사항,A/S등\n24시간 내 적극 해결해 드리며\nQSC 시스템을 통해 매장 운영을 체계적으로 관리합니다."
    },
    {
        id : 3,
        icon : "assets/cc_icon3.png",
        title : "SV 오픈 지원 시스템",
        text :  "오픈 3일 동안 오픈 세팅부터\n전체적인 운영 시뮬레이션 교육 및 컨설팅을 도와드립니다."
    },
    {
        id : 4,
        icon : "assets/cc_icon4.png",
        title : "안정적인 물류 시스템",
        text :  "전국적인 네트워크를 구축한 물류 시스템을 보유하고 있어,\n오배송 시 발 빠른 대처와 안정적인 영업이 가능합니다."
    }
]
function Coaching() {
  return (
    <Container>
      <Title>본사의 <TitleSpan>체계적인 코칭 전략</TitleSpan></Title>
      <SubTitle>카페봄봄의 차별화된 노하우를 경험해보세요!</SubTitle>
      <Contant>
        <Ul>
            {items.map((item)=>(
                <Li key={item.id}>
                    <Icon src={item.icon}></Icon>
                    <ConTitle>{item.title}</ConTitle>
                    <ConText>{item.text}</ConText>
                </Li>
            ))}
        </Ul>
        <LogoBox>
            <Logo src='assets/cc_logo.png'></Logo>
        </LogoBox>
      </Contant>
    </Container>
  )
}



export default Coaching
