import React, { useState } from 'react'
import styled from 'styled-components'
import { useNavigate } from "react-router-dom";

const Container = styled.div`
  position: relative;
`

const LanBtn = styled.button`
  position: relative;
  background-color: #fdda24;
  border-radius: 20px;
  padding: 5px 50px 5px 30px;
  font-size: 18px;
  font-weight: 800;
  cursor: pointer;
  z-index: 2;
`

const Arrow = styled.img`
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  width: 10px;
  transition: transform 0.3s;
  ${({ open }) => open && 'transform: translateY(-50%) rotate(180deg);'}
`

const LanguageBox = styled.div`
  position: absolute;
  top: 0;
  width: 100%;
  z-index: 1;
  display: ${({ open }) => (open ? 'block' : 'none')};
`

const Ul = styled.ul`
  background-color: #fdda24;
  border-radius: 20px;
  text-align: center;
  font-size: 18px;
  font-weight: bold;
  padding-top: 30px;
  padding-bottom: 10px;
`

const Li = styled.li`
  padding: 5px;
`

const StyledButton = styled.button`
  background: none;
  border: none;
  text-decoration: none;
  color: #000;
  font-size: 18px;
  cursor: pointer;
  &:hover {
    color: #333;
  }
`

const lan = [
  { id: 1, language: 'KOR', code: 'kor', path: '/' },
  { id: 2, language: 'ENG', code: 'eng', path: '/eng' },
  { id: 3, language: 'CHN', code: 'chn', path: '/chn' },
  { id: 4, language: 'JPN', code: 'jpn', path: '/jpn' }
];

function LanguageBtn() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();

  const toggleLanguageBox = () => setOpen(prev => !prev);

  const changeLanguage = (code, path) => {
    // ✅ HashRouter에 맞게 `/#`을 추가
    let newPath = path === '/' ? '/#/' : `${path}`;
  
    navigate(newPath);
    setOpen(false);
  };
  
  

  return (
    <Container>
      <LanBtn onClick={toggleLanguageBox}>
        LAN
        <Arrow src={`${process.env.PUBLIC_URL}/assets/downarrow.png`} alt="Arrow" open={open} />
      </LanBtn>
      <LanguageBox open={open}>
        <Ul>
          {lan.map((item) => (
            <Li key={item.id}>
              <StyledButton onClick={() => changeLanguage(item.code, item.path)}>
                {item.language}
              </StyledButton>
            </Li>
          ))}
        </Ul>
      </LanguageBox>
    </Container>
  )
}

export default LanguageBtn;
