import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/brandbrandbg.png) no-repeat left 6%;
    background-size: auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    @media screen and (max-width:768px) {
        padding: 50px 0;
    }
`
const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
`
const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 100px;
    @media screen and (max-width:768px) {
        font-size: 40px;   
    }
`
const Ul = styled.ul`
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 30px;
    margin-bottom: 50px;

    @media screen and (max-width:1240px) {
        flex-direction: column;
    }
`
const Li = styled.li`
    
`
const ConTitle = styled.h4`
    font-size: 22px;
    font-weight: 400;
    color: #333333;
    letter-spacing: -0.5px;
    margin-bottom: 25px;

    &::before{
        content: '';
    display: inline-block;
    width: 5px;
    height: 22px;
    background-color: #facd01;
    vertical-align: -2px;
    margin-right: 15px;
    }
`
const Img = styled.img`
    width: 100%;
`
const ColorBox = styled.div`
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 5px;
    margin-top: 50px;
`
const Color = styled.span`
    width: 120px;
    height: 120px;
    text-align: center;
    line-height: 120px;
    border-radius: 50%;
    &:first-child{
        background-color: #f4c722;
    }
    &:nth-child(2){
        background-color: #e16750;
    }
    &:nth-child(3){
        background-color: #e88071;
    }
    &:last-child{
        background-color: #f1ada7;
    }
`

const BottomBox = styled.div`
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 120px 0;
    width: 100%;
    border-radius: 16px;
    background-color: #f5b8b5;
`
const BottomUl = styled.ul`
    display: flex;
    @media screen and (max-width:1200px){
        flex-direction: column;
    }
`
const BottomLi = styled.li`
    width: 375px;
    height: 375px;
    background: url(assets/brandfl.png) no-repeat;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
`
const BconTitle = styled.span`
    font-size: 18px;
    color: #fff;
    margin-bottom: 30px;
    font-weight: 700;
`
const BconText = styled.p`
    text-align: center;
    color: #fff;
    font-size: 25px;
`
const ImgBox = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
`
const BImg = styled.img`
    display: inline-block;
`
function BI() {
  return (
    <Container>
      <Title>Cafe BOMBOM BI</Title>
      <SubTitle>당신을 위한 한 잔<br /><b>Cafe 봄봄</b></SubTitle>
      <Ul>
        <Li>
            <ConTitle>Brand Logo (Default)</ConTitle>
            <Img src={`${process.env.PUBLIC_URL}/assets/brand_logo_1.png`} />
        </Li>
        <Li>
            <ConTitle>Brand Logo (Simbol)</ConTitle>
            <Img src={`${process.env.PUBLIC_URL}/assets/brand_logo_2.png`} />
        </Li>
      </Ul>
      <Ul>
        <Li>
            <ConTitle>Word Mark (Type 1)</ConTitle>
            <Img src={`${process.env.PUBLIC_URL}/assets/brand_logo_3.png`} />
        </Li>
        <Li>
            <ConTitle>Word Mark (Type 2)</ConTitle>
            <Img src={`${process.env.PUBLIC_URL}/assets/brand_logo_4.png`} />
        </Li>
        <Li>
            <ConTitle>Brand Color</ConTitle>
            <ColorBox>
                <Color>Yellow</Color>
                <Color>Deep Pink</Color>
                <Color>Pink</Color>
                <Color>Light Pink</Color>
            </ColorBox>
        </Li>
      </Ul>
      <BottomBox>
        <BottomUl>
            <BottomLi>
                <BconTitle>Design Concept</BconTitle>
                <BconText>당신을 위한 한 잔과<br />휴식을 통해 행복이<br />커지는 공간</BconText>
            </BottomLi>
            <BottomLi>
                <BconTitle>Design Keyword</BconTitle>
                <BconText>당신을 위한 한 잔<br />·<br />더 커지는 행복</BconText>
            </BottomLi>
            <BottomLi>
                <BconTitle>Design Motif</BconTitle>
                <ImgBox>
                <BImg src={`${process.env.PUBLIC_URL}/assets/brand_icon1.png`} /><BconText>Grow Big<br />[ ; 커지다 ]</BconText>
                </ImgBox>
                <ImgBox>
                <BImg src={`${process.env.PUBLIC_URL}/assets/brand_icon2.png`} style={{height : "30px", marginTop : "15px"}} /><BconText>Cup<br />[ ; 커피잔 ]</BconText>
                </ImgBox>
               
            </BottomLi>
        </BottomUl>
      </BottomBox>
    </Container>
  )
}

export default BI
