import React, { useState } from 'react';
import styled from 'styled-components';

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background: url(assets/franchise/intebg.png) no-repeat top left;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin: 5px 0;
    padding: 100px 0 0 0;

    @media screen and (max-width: 768px) {
        padding: 50px 0;
    }
`;

const TableContainer = styled.div`
    width: 100%;
    max-width: 1200px;
    overflow-x: auto;
    margin-bottom: 50px;
    display: flex;
    flex-direction: column;
`;
const Note = styled.p`
    font-size: 13px;
    color: #ff3333;
    margin: 10px 0;
    align-self: flex-end;
`;
const Table = styled.table`
    width: 100%;
    border-collapse: collapse;
    text-align: center;
    font-size: 15px;
    color: #333;
    border-top: 2px solid #000;

    th {
        background-color: #f9f9f9;
        padding: 10px;
        border: 1px solid #ddd;
        font-weight: 700;
        text-align: center;
    }

    td {
        font-size: 14px;
        color: #585858;
        padding: 15px;
        border: 1px solid #ddd;
        text-align: left;
    }
`;

const Input = styled.input`
    width: 100%;
    max-width: 400px;
    height: 50px;
    font-size: 16px;
    font-weight: 700;
    color: #161615;
    padding: 0 20px;
    border: 1px solid #ddd;
    border-radius: 3px;

    &:focus {
        outline: 2px solid #fdda24;
    }
`;

const Select = styled.select`
    width: 100%;
    max-width: 400px;
    height: 50px;
    font-size: 16px;
    font-weight: 700;
    color: #161615;
    padding: 0 20px;
    border: 1px solid #ddd;
    border-radius: 3px;
`;

const TextArea = styled.textarea`
    width: 100%;
    height: 200px;
    padding: 10px;
    font-size: 16px;
    border: 1px solid #ddd;
    border-radius: 3px;
`;

const FormActions = styled.div`
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 20px;
`;

const CheckboxContainer = styled.label`
    display: flex;
    align-items: center;
    font-size: 14px;
    color: #555;
    cursor: pointer;
    
    input {
        margin-right: 8px;
    }
`;

const SubmitButton = styled.button`
    width: 200px;
    height: 50px;
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    background-color: ${({ disabled }) => (disabled ? '#ccc' : '#fdda24')};
    border: none;
    border-radius: 8px;
    cursor: ${({ disabled }) => (disabled ? 'not-allowed' : 'pointer')};

    &:hover {
        background-color: ${({ disabled }) => (disabled ? '#ccc' : '#e6c920')};
    }
`;

function Inquiry() {
    const [formData, setFormData] = useState({
        name: '',
        region: '',
        phone: '',
        store: '',
        size: '',
        age: '',
        budget: '',
        job: '',
        experience: '',
        timing: '',
        message: '',
    });

    const [isChecked, setIsChecked] = useState(false);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    const handleCheckboxChange = () => {
        setIsChecked(!isChecked);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!isChecked) {
            alert('개인정보취급방침에 동의해야 제출할 수 있습니다.');
            return;
        }
        console.log('폼 제출됨:', formData);
        alert('문의가 제출되었습니다.');
    };

    return (
        <Container>
            <TableContainer>
            <Note>* 전 항목 필수 입력 해주시길 바랍니다.</Note>
                <form onSubmit={handleSubmit}>
                    <Table>
                        <tbody>
                            {[
                                ['성함', 'name'],
                                ['창업희망지역', 'region'],
                                ['연락처', 'phone'],
                                ['매장희망평수', 'size'],
                                ['창업희망비용', 'budget'],
                                ['현직업', 'job'],
                                ['브랜드경험', 'experience'],
                                ['창업가능시기', 'timing'],
                            ].map(([label, name]) => (
                                <tr key={name}>
                                    <th>{label}</th>
                                    <td>
                                        <Input
                                            type="text"
                                            name={name}
                                            value={formData[name]}
                                            onChange={handleChange}
                                            required
                                        />
                                    </td>
                                </tr>
                            ))}
                            <tr>
                                <th>점포유무</th>
                                <td>
                                    <Select name="store" value={formData.store} onChange={handleChange} required>
                                        <option value="">선택</option>
                                        <option value="있음">있음</option>
                                        <option value="없음">없음</option>
                                    </Select>
                                </td>
                            </tr>
                            <tr>
                                <th>연령대</th>
                                <td>
                                    <Select name="age" value={formData.age} onChange={handleChange} required>
                                        <option value="">선택</option>
                                        <option value="20대">20대</option>
                                        <option value="30대">30대</option>
                                        <option value="40대">40대</option>
                                        <option value="50대">50대</option>
                                        <option value="60대 이상">60대 이상</option>
                                    </Select>
                                </td>
                            </tr>
                            <tr>
                                <th>문의내용</th>
                                <td>
                                    <TextArea
                                        name="message"
                                        value={formData.message}
                                        onChange={handleChange}
                                        required
                                    />
                                </td>
                            </tr>
                        </tbody>
                    </Table>
                    {/* 체크박스 + 서브밋 버튼 */}
                    <FormActions>
                        <CheckboxContainer>
                            <input
                                type="checkbox"
                                checked={isChecked}
                                onChange={handleCheckboxChange}
                            />
                            개인정보취급방침에 동의합니다.
                        </CheckboxContainer>
                        <SubmitButton type="submit" disabled={!isChecked}>
                            문의하기
                        </SubmitButton>
                    </FormActions>
                </form>
            </TableContainer>
        </Container>
    );
}

export default Inquiry;
