import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    background-color: #68482a;
    color: #fff;
    padding: 120px 0;
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    margin-top: 5px;
`
const Title = styled.h1`
    font-size: 63px;
    margin-bottom: 5px;
    @media screen and (max-width:768px){
        font-size: 28px;
    }
`
const TitleSpan = styled.span`
    color: #face00;
`
const Contant = styled.div`
    max-width: 1400px;
    width: 94%;
`
const Ul = styled.ul`
    display: flex;
    @media (max-width: 768px) {
    flex-wrap: wrap;
  }
`
const Li = styled.li`
    width: 23%;
    margin: 1%;
    height: 20em;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    position: relative;
    border: 0.4em solid #f4d7bc;
    border-image: linear-gradient(to top, #b38f60, #f4d7bc);
    border-image-slice: 1;
    @media (max-width: 768px) {
    width: 100%;
    height: 11em;
  }

`
const ConNumber = styled.h2`
    position: absolute;
    left: 0;
    top: 0;
    transform: translate(-50%,-50%);
    background-color: #68482a;
    width: 1.5em;
    height: 1.5em;
    text-align: center;
`
const ConTitle = styled.h2`
    white-space: pre-line;
`
const ConPoint = styled.h2`
    color: #face00;
`
const ConText = styled.p`
    text-align: center;
    white-space: pre-line;
    font-size: 0.7em;
`

const items = [
    {
        id: 1,
        title : "가맹비 500만원\n교육비 300만원\n보증금 200만원",
        point : "면제",
        text : "대구/경북/제주 이외지역 제외\n한시적면제"
    },
    {
        id: 2,
        title : "배달앱\nB2B계약",
        point : "수수료 할인",
        text : null
    },
    {
        id: 3,
        title : "인테리어",
        point : "NO마진",
        text : "직접 시공 가능"
    },
    {
        id: 4,
        title : "업종전환,",
        point : "브랜드 변경",
        text : "부분 리모델링 가능"
    },
    {
        id: 5,
        title : "SNS,온라인",
        point : "홍보 무상지원",
        text : null
    }
]

function Boon() {
  return (
    <Container>
      <Title>카페봄봄<TitleSpan> 창업 혜택</TitleSpan></Title>
      <Contant>
        <Ul>
            {items.map((item)=>(
                <Li key={item.id}>
                    <ConNumber>{item.id}</ConNumber>
                    <ConTitle>{item.title}</ConTitle>
                    <ConPoint>{item.point}</ConPoint>
                    <ConText>{item.text}</ConText>
                </Li>
            ))}
        </Ul>
      </Contant>
    </Container>
  )
}

export default Boon
