import React from 'react'
import styled from 'styled-components'

const Container = styled.div`
    width: 100%;
    border-radius: 16px;
    background-size: auto;
`
const TitleBox = styled.div`
    width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 50px 0;
    margin-bottom: 5px;
     background: url(assets/storybg.png) no-repeat left bottom;
     border: 1px solid #ccc;
     border-radius: 16px;
     
`
const Title = styled.p`
    font-size: 18px;
    font-weight: 800;
    color: #fdda24;
    margin-bottom: 20px;
    @media screen and (max-width:768px){
      margin-bottom: 5px;
    }
`
const SubTitle = styled.h3`
    font-size: 50px;
    font-weight: 200;
    color: #181818;
    line-height: 60px;
    text-align: center;
    margin-bottom: 50px;
    @media screen and (max-width:768px) {
        font-size: 24px;   
        margin-bottom: 5px;
        line-height: 40px;
    }
`
const About = styled.p`
    text-align: center;
    font-size: 16px;
    color: #9b9b9b;

`
const TextBox = styled.div`
    position: relative;
     display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 50px 0 50px 100px;
    border-radius: 16px;
    background: url(assets/storybg2.png) no-repeat center / cover ;
    @media screen and (max-width:768px){
        padding: 50px 0 50px 10px;
    }
`
const Text = styled.p`
    color: #fff;
    font-size: 24px;
    margin-bottom: 30px;
    align-self: flex-start;
`
const TextSpan = styled.span`
     color: #fdda24;
`
const SubText = styled.p`
    color: #fff;
    align-self: flex-start;
    @media screen and (max-width:768px){
        font-size: 12px;
    }
`
const WhiteBord = styled.div`
    width: 100%;
    padding: 50px 50px 100px 50px;
    max-width: 1400px;
    background-color: #fff;
    margin-top: 50px;
    align-self: flex-end;
    border-right: none;
    @media screen and (max-width:1400px){
        width: 90%;
    }
    @media screen and (max-width:768px){
        padding: 20px 20px 50px 20px;
    }
`
const Wh2 = styled.h2`
    font-weight: 400;
    margin-bottom: 50px;
`
const See = styled.div`
     width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    padding: 50px 0;
    margin: 5px 0;
    border: 1px solid #ccc;
    border-radius: 16px;
    background: url(assets/storybg3.png) no-repeat center /cover;
`
const GridBox = styled.div`
    display: grid;
    gap: clamp(5px, 2vw, 20px);  // 🌟 간격을 유동적으로 조정!
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); 
    grid-auto-rows: auto;  // 🌟 유동적인 높이로 설정!
    width: 100%;
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px;
`;

const GridItem = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 8px;  
gap: 10px;
padding: 20px;
`;
const GridImg = styled.img`
    width: 100px;
    height: 100px;
`
const GridTitle = styled.h3`

`
function Story() {
  return (
    <Container>
    <TitleBox>
     <Title>Cafe BOMBOM Office</Title>
     <SubTitle>Take-Out 전문 브랜드<br /><b>Cafe 봄봄</b></SubTitle>
     <About>Cafe 봄봄은 Take-Out 전문 카페로 출발하였습니다.<br />대학가에서 차별화 된 메뉴와 특별한 운영시스템으로 많은 학생들의 사랑을 받았습니다.<br />Take-Out 시장이 커지면서 Cafe 봄봄은 대학가를 넘어 중심가, 주택가 곳곳에서 한층 더 성장했습니다.</About>
     </TitleBox>
     <TextBox>
        <Text>차별화를 추구하여 보다<br />성장하여 <TextSpan>Cafe 봄봄</TextSpan></Text>
        <SubText>Cafe 봄봄은 2012년 부터 대구를 거점으로 성장해왔으며<br />2015년 가맹사업을 시작하였습니다. 지금은 서울/경기, 대구/경북,<br />부산/경남 등 전국 번화가 곳곳에 자리를 잡고 성업 중입니다.<br />그 배경에는 봄봄만의 특별한 메뉴와 매력이 있습니다.</SubText>
        <WhiteBord>
            <Wh2>Cafe 봄봄만의<br />특별한 메뉴와 매력</Wh2>
            <About style={{textAlign : "left"}}>‘보다 저렴한', '보다 맛있는', '보다 양이 많은', '보다 친절한', '보다 빠른' 커피와 음료로<br />매니아층을 형성하였으며, Take-Out 시장에서는 빠질 수 없는 카페로 인정받았습니다.<br />'Cafe 봄봄'은 현재에도 끊임없는 메뉴개발과 노력으로 성장을 거듭하고 있습니다.</About>
        </WhiteBord>
     </TextBox>
     <See>
        <Title>Brand Concept</Title>
        <SubTitle><b>봄</b>을 보다</SubTitle>
        <About>Cafe 봄봄은 봄이라는 밝고 산뜻한 분위기에 봄처럼 따스한 커피 한 잔의 작은 사치를 누릴 수 있는 행복한 공간입니다.<br />Cafe 봄봄에서 따스하고 산뜻한 봄을 한 잔 마시고, 잠시 여유를 가져보길 바라는 마음입니다.</About>
        <GridBox>
            <GridItem>
                <GridImg src={`${process.env.PUBLIC_URL}/assets/storygrid1.png`}></GridImg>
                <About>봄에피는 꽃과 같이 화사하고 밝은</About>
                <GridTitle>매장</GridTitle>
            </GridItem>
            <GridItem>
                <GridImg src={`${process.env.PUBLIC_URL}/assets/storygrid2.png`}></GridImg>
                <About>친절함과 발랄함이 돋보이는</About>
                <GridTitle>분위기</GridTitle>
            </GridItem>
            <GridItem>
                <GridImg src={`${process.env.PUBLIC_URL}/assets/storygrid3.png`}></GridImg>
                <About>꽃처럼 화려한 비주얼의</About>
                <GridTitle>음료</GridTitle>
            </GridItem>
        </GridBox>
        <Title>Target Customer</Title>
        <SubTitle><b>모든 연령대</b>가 즐길 수 있는<br />Cafe 봄봄</SubTitle>
        <About>afe 봄봄은 모든 연령대가 즐길 수 있는 매장입니다.<br />특히 중심가는 저렴한 가격에 맛있는 음료, 즉 가성비와 합리적 소비를 추구하는<br />10-30대의 트랜디한 고객과 충분하지 않은 시간으로 Take-Out을 주로 이용하는 바쁜 직장인에게 인기가 많습니다.<br />주거 밀집지역은 상대적으로 아침 시간을 여유롭게 즐기는 여성 고객, 병원 및 학원과 같은 오피스 고객층,<br />오후에는 하교 후의 중·고등학생을 타켓으로 하고 있습니다.</About>
     </See>
    </Container>
  )
}

export default Story
