import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import menudata from './MenuList.json'



const menuHeader = {
  id: 2,
  title: "메뉴소개",
  path: "/menu/newmenu",
  submenu: [
    { id: 6, title: "신제품", path: "/menu/newmenu",en:"NEW",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab01.png` },
    { id: 7, title: "커피", path: "/menu/coffee",en:"COFFEE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab02.png` },
    { id: 8, title: "라떼", path: "/menu/latte",en:"LATTE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab02.png` },
    { id: 9, title: "스무디", path: "/menu/smoothie",en:"SMOOTHIE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab03.png` },
    { id: 10, title: "에이드", path: "/menu/ade",en:"ADE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab04.png` },
    { id: 11, title: "티", path: "/menu/tea",en:"TEA",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab05.png` },
    { id: 12, title: "주스", path: "/menu/juice",en:"JUICE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab06.png` },
    { id: 13, title: "버블티", path: "/menu/bubbletea",en:"BUBBLE",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab07.png` },
    { id: 14, title: "사이드메뉴", path: "/menu/sidemenu",en:"SIDE MENU",icon: `${process.env.PUBLIC_URL}/assets/menu/ico_tab08.png` }
  ]
};

const Container = styled.div`
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 100px 0;
  @media screen and (max-width:768px){
    padding: 50px 0;
  }
`;

const TabMenu = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 10px 20px;
  border-radius: 10px;
  flex-wrap: wrap;
  @media screen and (max-width:850px){
    padding: 0;
  }
`;
const TabImg = styled.img`
    width: 35px;
    height: 50px;
    @media screen and (max-width:768px){
    width: 20px;
    height: 35px;
  }
`
const TabSpan = styled.span`
    font-size: 13px;
    color: ${({ $active }) => ($active ? '#fff' : '#d4d4d4')};
    letter-spacing: 2px;
    padding: 10px 0;
    @media screen and (max-width:768px){
    font-size: 7px;
  }
`
const TabButton = styled.button`
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 151px;
    height: 170px;
  padding: 10px 15px;
  font-size: 24px;
    color: #181818;
  border: none;
  border-radius: 5px;
  background-color: ${({ $active }) => ($active ? '#ffcc00' : '#f8f8f8')};
  font-weight: bold;
  cursor: pointer;
  transition: 0.3s;
  &:hover {
    background: #ffcc00;
    color: #000;
  }
  @media screen and (max-width:768px){
    width: 80px;
    height: 100px;
    font-size: 13px;
    
  }
`;

const Content = styled.div`
  margin-top: 20px;
  padding: 20px;
  width: 100%;
  max-width: 1400px;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  text-align: center;
`;

const MenuList = styled.div`
  list-style: none;
  padding: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
`;

const MenuItem = styled.div`
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
   position: relative;
  margin: 10px 0;
  font-size: 18px;
  &:hover .hover-button {
    opacity: 1;
    transform: translateY(0);
  }
`;
const MenuImg = styled.img`
    width: 100%;
    border: 1px solid #ccc;
    border-radius: 50%;
    
`
const HoverButton = styled.button`
  position: absolute;
  bottom: 50%;
  transform: translateY(10px);
  background: rgba(0, 0, 0, 0.8);
  color: #fff;
  border: none;
  padding: 10px 20px;
  border-radius: 5px;
  font-size: 14px;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.3s ease-in-out, transform 0.3s ease-in-out;
`;
const MenuEn = styled.span`
    font-size: 15px;
    color: #9b9b9b;
    line-height: 30px;

`
const MenuTitle = styled.h3`
    font-size: 25px;
    font-weight: 700;
    color: #181818;
    letter-spacing: -0.5px;
`
const Pagenation = styled.div`
    margin-top: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
`;
const LeftArrow = styled.button`
  width: 30px;
  height: 30px;
  background: url(assets/storeleft.png) no-repeat 50% 50%;
  color: transparent;
  border-radius: 50%;
  transition: all 0.5s;
  &:hover {
    background-color: #000;
  }
`
const RightArrow = styled.button`
  width: 30px;
  height: 30px;
   background: url(assets/storeright.png) no-repeat 50% 50%;
   color: transparent;
   border-radius: 50%;
   transition: all 0.5s;
  &:hover {
    background-color: #000;
  }
`
const NumBtn = styled.button`
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background-color: ${(props) => (props.$active ? '#000' : '#fff')};
    color: ${(props) => (props.$active ? '#fff' : '#d4d4d4')};
    font-weight: bold;
    font-size: 18px;
    cursor: pointer;
    transition: all 0.5s;
    &:hover {
        background-color: #000;
        color: #fff;
    }
`;
function Menu() {
    const location = useLocation();
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState("newmenu");
    const [currentPage, setCurrentPage] = useState(1);
    const ITEMS_PER_PAGE = 12;
  
    useEffect(() => {
      const activeItem = menuHeader.submenu.find((item) => item.path === location.pathname);
      if (activeItem && activeItem.path.replace('/menu/', '') !== activeTab) {
        setActiveTab(activeItem.path.replace('/menu/', ''));
        setCurrentPage(1);
      }
    }, [location.pathname, activeTab]);
  
    const currentMenu = menudata?.[activeTab] || [];
    const totalPages = Math.ceil(currentMenu.length / ITEMS_PER_PAGE);
  
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const paginatedMenu = currentMenu.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  
    return (
      <Container>
        <TabMenu>
          {menuHeader.submenu.map((category) => {
            const categoryKey = category.path.split("/")[2];
            const isActive = activeTab === categoryKey;
            const iconSrc = isActive ? category.icon.replace(".png", "_on.png") : category.icon;
  
            return (
              <TabButton key={category.id} $active={isActive} onClick={() => navigate(category.path)}>
  <TabImg src={category.icon.replace(/(\.\w+)$/, isActive ? "_on$1" : "$1")} alt={category.title} />
  <TabSpan $active={isActive}>{category.en}</TabSpan>
  {category.title}
</TabButton>
            );
          })}
        </TabMenu>
  
        <Content>
          {paginatedMenu.length > 0 ? (
            <MenuList>
              {paginatedMenu.map((item, index) => (
                <MenuItem key={index}>
                  <MenuImg src={process.env.PUBLIC_URL + item.img} alt={item.name} />
                  <HoverButton className="hover-button">자세히보기 &gt;</HoverButton>
                  <MenuEn>{item.enname}</MenuEn>
                  <MenuTitle>{item.name}</MenuTitle>
                </MenuItem>
              ))}
            </MenuList>
          ) : (
            <p>해당 카테고리에 대한 메뉴가 없습니다.</p>
          )}
  
          {totalPages > 1 && (
            <Pagenation>
  {currentPage > 1 && (
    <LeftArrow onClick={() => setCurrentPage(currentPage - 1)}>
      처음
    </LeftArrow>
  )}
              {Array.from({ length: totalPages }, (_, index) => (
                <NumBtn key={index} $active={currentPage === index + 1} onClick={() => setCurrentPage(index + 1)}>
                  {index + 1}
                </NumBtn>
              ))}
             {currentPage < totalPages && ( 
  <RightArrow onClick={() => setCurrentPage((prev) => prev + 1)} />
)}
            </Pagenation>
          )}
        </Content>
      </Container>
    );
  }
  
  export default Menu;
